async (page) => {
  const summary = page.locator('summary.navlink--search').filter({ visible: true }).first();
  await summary.click();
  const input = page.locator('header-search-popdown input[type="search"]').filter({ visible: true }).first();
  await input.click();
  await input.pressSequentially('dress', { delay: 80 });
  await page.waitForTimeout(3000);
  return await page.evaluate(() => ({ theme: window.Shopify.theme.id, vw: innerWidth }));
}

