() => {
  const root = [...document.querySelectorAll('.predictive-search')].find(e => e.offsetParent);
  const cs = (el, props) => { if(!el) return null; const s = getComputedStyle(el); return Object.fromEntries(props.map(p=>[p, s.getPropertyValue(p)])); };
  const r = el => { if(!el) return null; const b = el.getBoundingClientRect(); return [Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)]; };
  const layout = root?.querySelector('.predictive-search__layout');
  const sugg = root?.querySelector('[aria-label] mark, .predictive-search__link mark, mark') ;
  const link = sugg?.closest('a');
  const cards = [...(root?.querySelectorAll('.predictive-search__products__list > *, .predictive-search__product, [class*=product-item]')||[])].filter(e=>e.offsetParent).slice(0,4);
  const img = root?.querySelector('img');
  return {
    layoutHTMLhead: layout?.outerHTML.slice(0, 600),
    layout: cs(layout, ['display','grid-template-columns','gap','--columns','padding-left','padding-right','max-width']), layoutRect: r(layout),
    columns: [...(layout?.children||[])].map(c=>({cls:c.className, rect:r(c), gtc: getComputedStyle(c).gridTemplateColumns})),
    suggLinkHTML: link?.outerHTML.slice(0,400),
    suggLink: cs(link, ['font-family','font-size','font-weight','line-height','letter-spacing','text-transform','color']),
    mark: cs(sugg, ['font-family','font-size','font-style','font-weight','background-color','color','padding','text-decoration']),
    productsList: (() => { const l = root?.querySelector('.predictive-search__products__list'); return {cls:l?.className, rect:r(l), s: cs(l,['display','grid-template-columns','gap','column-gap','row-gap'])}; })(),
    cards: cards.map(c=>({cls:c.className.slice(0,120), rect:r(c)})),
    img: { sizes: img?.sizes, srcset: img?.srcset?.slice(0,200), rect: r(img), currentSrc: img?.currentSrc, cls: img?.className, aspect: img && getComputedStyle(img.parentElement).aspectRatio, parentCls: img?.parentElement.className },
    heading: cs(root?.querySelector('.predictive-search__heading'), ['font-family','font-size','font-weight','text-transform','letter-spacing','margin-bottom']),
    searchFor: (() => { const a=[...root.querySelectorAll('a,button')].find(x=>/search for/i.test(x.textContent)); return {html:a?.outerHTML.slice(0,300), s: cs(a,['font-family','font-size','text-transform','letter-spacing','border-bottom','text-decoration'])}; })(),
