() => {
  const m = document.querySelector('[data-nosto-autocomplete]');
  const cs = (el, props) => { if(!el) return null; const s = getComputedStyle(el); return Object.fromEntries(props.map(p=>[p, s.getPropertyValue(p)])); };
  const r = el => { if(!el) return null; const b = el.getBoundingClientRect(); return [Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)]; };
  const kw = [...m.querySelectorAll('a, button, li, div')].find(e => /midi/.test(e.textContent) && e.children.length <= 3 && e.textContent.trim().length < 20);
  const strong = kw?.querySelector('*');
  const layout = m.querySelector('.predictive-search__layout');
  const g = m.querySelector('.predictive-search__products__list .grid, .grid');
  const img = g?.querySelector('img');
  return {
    theme: Shopify.theme.id,
    mountStyle: m.getAttribute('style'),
    layout: cs(layout, ['grid-template-columns','--columns']), layoutRect: r(layout),
    kwHTML: kw?.outerHTML.slice(0, 400), kw: cs(kw, ['font-family','font-size','font-weight']), inner: cs(strong, ['font-family','font-weight','font-style','background-color','color']),
    grid: { html: g?.outerHTML.slice(0,300), s: cs(g, ['display','grid-template-columns','gap','--columns']), count: g?.children.length },
    item: { cls: g?.firstElementChild?.className, rect: r(g?.firstElementChild) },
    img: { sizes: img?.sizes, currentSrc: img?.currentSrc, rect: r(img) },
    listParent: g?.parentElement?.className,
  };
}

