input.function:
() => {
  const m = [...document.querySelectorAll('[data-nosto-autocomplete]')].find(x => x.innerHTML.length);
  const cs = (el, props) => { if(!el) return null; const s = getComputedStyle(el); return Object.fromEntries(props.map(p=>[p, s.getPropertyValue(p)])); };
  const r = el => { if(!el) return null; const b = el.getBoundingClientRect(); return [Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)]; };
  const layout = m.querySelector('.predictive-search__layout');
  const link = m.querySelectorAll('.predictive-search__link')[1];
  const g = m.querySelector('.predictive-search__products__list .grid');
  const item = g?.firstElementChild;
  const img = g?.querySelector('img');
  const imgWrap = item?.querySelector('.product-item__image');
  return {
    layout: cs(layout, ['grid-template-columns','--columns']), layoutRect: r(layout),
    linkHTML: link?.outerHTML.slice(0,400), link: cs(link, ['font-family','font-size','font-weight','line-height']),
    inner: cs(link?.querySelector('span *'), ['font-family','font-weight','font-style','background-color','color']),
    grid: cs(g, ['display','grid-template-columns','gap','--columns']), count: g?.children.length,
    item: { cls: item?.className, rect: r(item) },
    imgWrapPadTop: imgWrap && getComputedStyle(imgWrap).paddingTop,
    img: { sizes: img?.sizes, currentSrc: img?.currentSrc, rect: r(img) },
  };
}

