### Ran Playwright code
```js
await (async (page) => {
  const out = {};
  for (const [label, theme, extra] of [['live', '157927932041', ''], ['dev', '158466539657', '&nostodebug=true']]) {
    out[label] = {};
    for (const w of [390, 600, 820, 1100]) {
      await page.setViewportSize({ width: w, height: 900 });
      await page.goto(`https://www.elietahari.com/?preview_theme_id=${theme}${extra}`);
      await page.waitForTimeout(4000);
      const opened = await page.evaluate(() => {
        document.querySelectorAll('csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.remove());
        const s = [...document.querySelectorAll('header-search-popdown summary, summary[title="Search"]')].find(e => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden');
        s?.click(); return s?.className;
      });
      await page.waitForTimeout(1200);
      const inp = page.locator('header-search-popdown input[type="search"]').filter({ visible: true }).first();
      if (!(await inp.count())) { out[label][w] = { opened, input: false }; continue; }
      await inp.focus();
      await page.keyboard.type('dress', { delay: 80 });
      await page.waitForTimeout(4000);
      await page.screenshot({ path: `.playwright-mcp/qa/${label}-ac-dress-${w}.png` });
      out[label][w] = await page.evaluate(() => {
        const g = [...document.querySelectorAll('.predictive-search__products__list .grid')].find(e => e.offsetParent);
        if (!g) return { id: Shopify.theme.id, grid: null };
        const s = getComputedStyle(g);
        return { id: Shopify.theme.id, gtc: s.gridTemplateColumns, cols: s.getPropertyValue('--columns'), count: g.children.length,
          card: Math.round(g.firstElementChild.getBoundingClientRect().width),
          img: g.querySelector('img')?.currentSrc?.match(/width=\d+/)?.[0],
          layout: getComputedStyle(g.closest('.predictive-search__layout')).gridTemplateColumns };
      });
    }
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
})(page);
```
