async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  const out = {};
  for (const [label, theme, extra] of [['live', '157927932041', ''], ['dev', '158466539657', '&nostodebug=true']]) {
    await page.goto(`https://www.elietahari.com/search?q=dress&preview_theme_id=${theme}${extra}`);
    await page.waitForTimeout(6000);
    out[label] = await page.evaluate(() => {
      const groups = [...document.querySelectorAll('[data-collapsible], .filter-group, details, [class*=filter-group]')]
        .filter(g => /size/i.test(g.querySelector('summary, button, [data-collapsible-trigger], .filter-group__heading, h3, h4')?.textContent || ''));
      const g = groups[0];
      return { id: Shopify.theme.id, count: groups.length,
        heading: g?.querySelector('summary, button, [data-collapsible-trigger], h3, h4')?.textContent.trim().replace(/\s+/g,' '),
        values: g ? [...g.querySelectorAll('label, li')].map(l => l.textContent.trim().replace(/\s+/g, ' ')).filter(Boolean).slice(0, 80) : null,
        allHeadings: [...document.querySelectorAll('[data-collapsible-trigger], .filter-group__heading, summary')].map(e=>e.textContent.trim().replace(/\s+/g,' ')).filter(t=>t.length<40).slice(0,30) };
    });
  }
  return out;
}

