input.code:
async (page) => {
  const bodies = [];
  const h = async r => { if (/search\.nosto\.com/.test(r.url()) && r.request().method() === 'POST') { try { bodies.push(await r.json()); } catch {} } };
  page.on('response', h);
  await page.goto(`https://www.elietahari.com/search?q=dress&preview_theme_id=158466539657&nostodebug=true`);
  await page.waitForTimeout(7000);
  page.off('response', h);
  const id = await page.evaluate(() => Shopify.theme.id);
  const main = bodies.find(b => JSON.stringify(b).includes('"facets"'));
  const facets = main?.data?.search?.products?.facets;
  const drawer = await page.evaluate(() => [...document.querySelectorAll('[data-nosto-filters] [data-collapsible-trigger], [data-nosto-filters] .filter-group__heading, [data-nosto-filters] summary')].map(e => e.textContent.trim().replace(/\s+/g, ' ')));
  return { id, facets: facets?.map(f => ({ id: f.id, name: f.name, field: f.field, type: f.type, min: f.min, max: f.max })), drawer };
}

