toolUseResult.originalFile:
/**
 * Everything the theme passes to Nosto. The theme renders these mount points and writes the
 * "RS: Nosto Settings" values onto them as data-* attributes (snippets/rs-nosto-results.liquid,
 * snippets/header-search-popdown.liquid). Every value has a fallback, so Nosto still works on a theme
 * that doesn't output an attribute. Grid columns don't pass through here: the theme sets its own
 * --COLUMNS variables on the mounts. On the collection page the theme also renders shortcut filters and
 * editorial tiles into <template>s, since it already has the collection's context (no extra request).
 */

export const selectors = {
  // header search dropdown, one per search popdown (desktop, mobile, mobile menu)
  dropdown: "[data-nosto-autocomplete]",
  // search input and form, looked up inside the dropdown's own form
  searchInput: 'input[name="q"]',
  searchForm: "form",
  // results mount: search page or collection page (only one exists per page)
  results: "[data-nosto-search], [data-nosto-collection]",
  // theme-rendered HTML on the collection page (sections/collection.liquid), next to the mount
  shortcutFilters: "template[data-nosto-shortcut-filters]",
  editorialTiles: "template[data-nosto-editorial-tile]",
  // theme-rendered Model | Product image switcher (snippets/collection-model-switcher.liquid).
  // Sits outside the mount, since the Portal clears the mount on first render.
  modelSwitcher: "template[data-nosto-model-switcher]",
  // translated theme copy (snippets/nosto-i18n.liquid); read in lib/i18n.ts
  i18n: "[data-nosto-i18n]"
}

/** Which image a product card leads with. The theme's Model | Product switcher toggles it client-side. */
export const cardImageModes = ["model", "product"] as const
export type CardImageMode = (typeof cardImageModes)[number]

export const paginationTypes = ["numbers", "load-more", "infinite"] as const
export type PaginationType = (typeof paginationTypes)[number]

/** Fallbacks, matching the theme setting defaults */
export const themeDefaults = {
  pagination: "numbers" as PaginationType,
  /** Search page: same as the theme's `paginate search.results by 36` */
  pageSize: 36,
  /** The theme's predictive search dropdown shows 3 */
  autocompleteProducts: 3,
  /** Default card image, matching the search section's `card_image_mode` default */
  cardImageMode: "model" as CardImageMode
}

function readData(selector: string): DOMStringMap {
  return document.querySelector<HTMLElement>(selector)?.dataset ?? {}
}

/** Liquid writes booleans as "true" / "false"; a missing attribute keeps the fallback */
function readFlag(value: string | undefined, fallback = true) {
  return value === undefined ? fallback : value !== "false"
}

function readNumber(value: string | undefined, fallback: number, min: number, max: number) {
  const number = Number(value)
  return value && Number.isInteger(number) ? Math.min(max, Math.max(min, number)) : fallback
}

/** Page numbers, "Load more" or infinite scroll (`data-pagination`) */
export function getPaginationType(): PaginationType {
  const value = readData(selectors.results).pagination
  return paginationTypes.find(type => type === value) ?? themeDefaults.pagination
}

/**
 * "Load more" and infinite scroll append pages, so the URL stores how many pages are loaded
 * and a reload fetches all of them from the start.
 */
export function appendsPages() {
  return getPaginationType() !== "numbers"
}

/** Products per page (`data-page-size`, collection page); the search page uses the default */
export function getPageSize() {
  return readNumber(readData(selectors.results).pageSize, themeDefaults.pageSize, 1, 100)
}

/**
 * Which parts the header search dropdown shows, and how many products.
 * `popularSearches` defaults off: the theme's own dropdown (sections/predictive-search.liquid) has no
 * popular-searches group, so showing one would add something the shopper doesn't see today.
 */
export function getAutocompleteSettings() {
  const data = readData(selectors.dropdown)
  return {
    suggestions: readFlag(data.suggestions),
    collections: readFlag(data.collections),
    popularSearches: readFlag(data.popularSearches, false),
    searchButton: readFlag(data.searchButton),
    products: readNumber(data.products, themeDefaults.autocompleteProducts, 3, 12)
  }
}

/**
 * Elie Tahari-only options, read from the results mount. These come from Liquid *section* settings on
 * sections/search.liquid (not the global "RS: Nosto Settings" group), because the theme already exposes
 * them per section — but the read is the same.
 */

/** `data-card-image-mode`: which image the card leads with (sections/search.liquid `card_image_mode`) */
export function getCardImageMode(): CardImageMode {
  const value = readData(selectors.results).cardImageMode
  return cardImageModes.find(mode => mode === value) ?? themeDefaults.cardImageMode
}

/** `data-enable-sort` / `data-enable-filters`: the section's own toggles for the toolbar */
export function getToolbarSettings() {
  const data = readData(selectors.results)
  return {
    sort: readFlag(data.enableSort),
    filters: readFlag(data.enableFilters)
  }
}

/** Shortcut filter buttons (snippets/rs-shortcut-filter-buttons.liquid); empty when the collection has none */
export function getShortcutFiltersHtml() {
  return document.querySelector<HTMLTemplateElement>(selectors.shortcutFilters)?.innerHTML.trim() ?? ""
}

export type GridTile = {
  /** 1-based slot in the whole grid, counting products and tiles */
  position: number
  html: string
}

/** Editorial tiles (snippets/rs-collection-content-blocks.liquid, "RS: Metaobject-driven editorial images") */
export function getEditorialTiles(): GridTile[] {
  return Array.from(document.querySelectorAll<HTMLTemplateElement>(selectors.editorialTiles)).map(template => ({
    position: readNumber(template.dataset.position, 1, 1, 10000),
    html: template.innerHTML
  }))
}

