import { SearchTermsFacet } from "@nosto/nosto-js/client"
import { cl } from "@nosto/search-js/utils"
import { useOptimisticFacet } from "@/lib/hooks/useOptimisticFacet"
import ThemeIcon from "@/elements/ThemeIcon"
import { handleize } from "@/lib/utils"
import FilterGroup from "@/shared/filters/FilterGroup"
import { strings } from "@/lib/i18n"

type Props = {
  facet: SearchTermsFacet
}

/** Values shown before the "More options" link, like the theme */
const visibleValues = 10

/**
 * Checkbox list facet using the theme's markup (snippets/filters.liquid, list filters), so collection-bar.css
 * styles the rows and checkboxes.
 */
export default function TermsFacet({ facet }: Props) {
  const { optimisticData, selectedFiltersCount, toggleProductFilter } = useOptimisticFacet(facet)
  const [showAll, setShowAll] = useState(false)
  const isColor = facet.name.toLowerCase() === "color"

  return (
    <FilterGroup title={facet.name} count={selectedFiltersCount}>
      <ul className="collection-nav" data-nosto-element="facet">
        {optimisticData.map((value, index) => {
          const id = `nosto-filter-${facet.id}-${index}`
          return (
            <li
              key={value.value}
              className={cl(
                "sidebar__item",
                value.selected ? "sidebar__item--active link--remove" : "link--add",
                !showAll && index >= visibleValues && "hidden"
              )}
            >
              <input
                type="checkbox"
                id={id}
                checked={value.selected}
                onChange={() => toggleProductFilter(facet.field, value.value, !value.selected)}
              />
              <label className="filter-group__label" htmlFor={id}>
                {isColor && (
                  <span
                    className="rs-filter__color-swatch filter-group__swatch"
                    style={{ background: `var(--${handleize(value.value)})` }}
                  />
                )}
                <span className="filter-group__text">{value.value}</span>
                <span className="filter-group__count">({value.count})</span>
              </label>
            </li>
          )
        })}
      </ul>
      {!showAll && optimisticData.length > visibleValues && (
        <div className="collection__sidebar__actions">
          <button type="button" className="collection__sidebar__link" onClick={() => setShowAll(true)}>
            <ThemeIcon name="arrow-separate-vertical" />
            <span>{strings().showMore}</span>
          </button>
        </div>
      )}
    </FilterGroup>
  )
}

