import { afterEach, describe, expect, it } from "vitest"
import {
  appendsPages,
  getAutocompleteSettings,
  getCardImageMode,
  getEditorialTiles,
  getPageSize,
  getPaginationType,
  getShortcutFiltersHtml,
  getToolbarSettings,
  themeDefaults
} from "@/lib/themeSettings"
import { getQueryFromUrlState, updateUrlFromQuery } from "@/lib/url"

function setResultsContainer(pagination?: string) {
  document.body.innerHTML = pagination
    ? `<div data-nosto-search data-pagination="${pagination}"></div>`
    : "<div data-nosto-search></div>"
}

describe("Elie Tahari section settings", () => {
  afterEach(() => {
    document.body.innerHTML = ""
  })

  it("defaults to the model image and a full toolbar", () => {
    document.body.innerHTML = "<div data-nosto-search></div>"
    expect(getCardImageMode()).toBe(themeDefaults.cardImageMode)
    expect(getToolbarSettings()).toEqual({ sort: true, filters: true })
  })

  it("reads the section's card image mode", () => {
