async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto(`https://www.elietahari.com/search?q=dress&preview_theme_id=157927932041`);
  await page.waitForTimeout(5000);
  return await page.evaluate(() => {
    const items = [...document.querySelectorAll('input[name="filter.v.t.shopify.color-pattern"]')].map(i => {
      const li = i.closest('li'); const sw = li?.querySelector('.swatch__button');
      return { label: li?.textContent.trim().replace(/\s+/g,' '), value: i.value, swHTML: sw?.outerHTML.slice(0, 260), bg: sw && getComputedStyle(sw).backgroundColor, bgImg: sw && getComputedStyle(sw).backgroundImage.slice(0,80) };
    });
    return { id: Shopify.theme.id, items: items.filter((x, i, a) => a.findIndex(y => y.value === x.value) === i) };
  });
}

