input.function:
async () => {
  const handles = [...new Set([...document.querySelectorAll('a[href*="/products/"]')].map(a => new URL(a.href).pathname.split('/products/')[1]?.split('?')[0]).filter(Boolean))].slice(0, 6);
  const out = [];
  for (const h of handles) {
    const p = await (await fetch(`/products/${h}.js`)).json();
    out.push({ h, tags: p.tags, options: p.options?.map(o => ({ name: o.name, values: o.values.slice(0, 4) })) });
  }
  return { id: Shopify.theme.id, out };
}

