input.code:
async (page) => {
  await page.goto(`https://www.elietahari.com/search?q=dress&preview_theme_id=158466539657&nostodebug=true`);
  await page.waitForTimeout(6000);
  return await page.evaluate(async () => {
    const api = await new Promise(r => window.nostojs(r));
    const res = await api.search({ query: 'dress', products: { size: 100, fields: ['productId', 'name', 'tags1'], preFilter: [{ not: [{ field: 'tags1', value: ['hide'] }] }] } }, {});
    const hits = res.products.hits;
    const colorTags = hits.map(h => (h.tags1 || []).filter(t => /^COLOR_/i.test(t)));
    const counts = {};
    colorTags.flat().forEach(t => counts[t] = (counts[t] || 0) + 1);
    return { id: Shopify.theme.id, total: res.products.total, sampled: hits.length,
      withColorTag: colorTags.filter(t => t.length).length, multi: colorTags.filter(t => t.length > 1).length,
      missing: hits.filter((h, i) => !colorTags[i].length).map(h => h.name).slice(0, 10), counts };
  });
}

