input.code:
async (page) => {
  const bodies = [];
  const h = async r => { if (/search\.nosto\.com/.test(r.url()) && r.request().method() === 'POST') { try { bodies.push({ req: r.request().postData(), res: await r.json() }); } catch {} } };
  page.on('response', h);
  await page.goto(`https://www.elietahari.com/search?q=dress&filter.skus.customFields.color=Amethyst&preview_theme_id=158466539657&nostodebug=true`);
  await page.waitForTimeout(7000);
  page.off('response', h);
  const id = await page.evaluate(() => Shopify.theme.id);
  const main = bodies.find(b => JSON.stringify(b.res).includes('"facets"'));
  const color = main?.res?.data?.search?.products?.facets?.find(f => f.name === 'Color');
  const q = main?.req || '';
  return { id, facetQuery: (q.match(/facets\s*\{[^]*?\}\s*\}/) || [q.slice(q.indexOf('facets'), q.indexOf('facets') + 600)])[0],
    amethyst: color?.data?.filter(d => /amethyst/i.test(d.value)), sample: color?.data?.slice(0, 2), keys: color && Object.keys(color) };
}

