input.content:
import { SearchFacetValueVisual } from "@nosto/nosto-js/client"
import { cl } from "@nosto/search-js/utils"
import { SwatchStyle } from "@/lib/themeSettings"

type Props = {
  /** Set per value in Nosto Admin (facet value → Image / Color / None) */
  visual?: SearchFacetValueVisual | null
  style: SwatchStyle
}

/**
 * The theme's filter swatch (snippets/filters.liquid, `filter.presentation == 'swatch'`), fed from Nosto's
 * facet value visual instead of Shopify's `filter_value.swatch`. A value without one gets the theme's empty
 * swatch, as Multicolor does in the theme's own filter.
 */
export default function FilterSwatch({ visual, style }: Props) {
  const className = `swatch__button swatch__button--${style}`

  return (
    <div className="shopify-swatch">
      {visual?.type === "thumbnail" ? (
        <div className={className}>
          <img src={visual.value} width={24} height={24} alt="" loading="lazy" />
        </div>
      ) : visual?.type === "color" ? (
        <div
          className={className}
          data-swatch={visual.value.toLowerCase() === "#ffffff" ? "white" : undefined}
          style={{ backgroundColor: visual.value }}
        />
      ) : (
        <div className={cl(className, "swatch__button--empty")} />
      )}
    </div>
  )
}

