import { render } from "@testing-library/preact"
import { describe, expect, it } from "vitest"
import FilterSwatch from "@/shared/filters/FilterSwatch"

function swatch(props: Parameters<typeof FilterSwatch>[0]) {
  const { container } = render(<FilterSwatch {...props} />)
  return container.querySelector<HTMLElement>(".shopify-swatch .swatch__button")!
}

describe("FilterSwatch", () => {
  it("renders a colour visual as the theme's colour swatch", () => {
    const button = swatch({ visual: { type: "color", value: "#A54DCF" }, style: "square" })
    expect(button.className).toBe("swatch__button swatch__button--square")
    expect(button.style.backgroundColor).toBe("rgb(165, 77, 207)")
    expect(button.dataset.swatch).toBeUndefined()
  })

  it("marks white like the theme, so it keeps a border", () => {
    expect(swatch({ visual: { type: "color", value: "#FFFFFF" }, style: "square" }).dataset.swatch).toBe("white")
  })

  it("renders a thumbnail visual as an image swatch", () => {
    const button = swatch({ visual: { type: "thumbnail", value: "https://example.com/print.jpg" }, style: "circle" })
    expect(button.className).toBe("swatch__button swatch__button--circle")
    expect(button.querySelector("img")?.getAttribute("src")).toBe("https://example.com/print.jpg")
  })

  it("falls back to the theme's empty swatch without a visual", () => {
    expect(swatch({ visual: null, style: "square" }).classList.contains("swatch__button--empty")).toBe(true)
  })
})

