async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto(`https://www.elietahari.com/search?q=dress&preview_theme_id=158466539657&nostodebug=true`);
  await page.waitForTimeout(8000);
  const info = await page.evaluate(() => {
    const m = document.querySelector('[data-nosto-search]');
    const rows = [...document.querySelectorAll('[data-nosto-filters] li')].filter(li => li.querySelector('.shopify-swatch'));
    const pick = rows.slice(0, 3).map(li => { const b = li.querySelector('.swatch__button'); const s = getComputedStyle(b);
      return { label: li.textContent.trim(), cls: b.className, bg: s.backgroundColor, w: s.width, h: s.height, border: s.border, html: li.querySelector('label').outerHTML.slice(0, 300) }; });
    return { id: Shopify.theme.id, attrs: { sw: m.dataset.swatches, style: m.dataset.swatchStyle }, swatchRows: rows.length, pick };
  });
  // open drawer + color group for screenshot
  await page.evaluate(() => {
    document.querySelectorAll('csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.remove());
    [...document.querySelectorAll('button')].find(b => /^filter/i.test(b.textContent.trim()) && b.offsetParent)?.click();
  });
  await page.waitForTimeout(1500);
  await page.evaluate(() => [...document.querySelectorAll('[data-nosto-filters] summary')].find(s => /color/i.test(s.textContent))?.click());
  await page.waitForTimeout(1000);
  await page.screenshot({ path: '.playwright-mcp/qa/dev-filter-swatch.png' });
  return info;
}

