async (page) => {
  const bodies = [];
  const h = async r => { if (/search\.nosto\.com/.test(r.url()) && r.request().method() === 'POST') { try { bodies.push(await r.json()); } catch {} } };
  page.on('response', h);
  await page.goto('https://www.baublebar.com/search?q=necklace');
  await page.waitForTimeout(9000);
  page.off('response', h);
  const main = bodies.find(b => JSON.stringify(b).includes('"facets"'));
  const facets = main?.data?.search?.products?.facets;
  const shopifyFilters = await page.evaluate(() => [...new Set([...document.querySelectorAll('input[name^="filter."]')].map(i => i.name))]);
  return { theme: await page.evaluate(() => window.Shopify?.theme?.name), nostoResponses: bodies.length,
    facets: facets?.map(f => ({ name: f.name, field: f.field, type: f.type, sample: f.data?.slice(0, 5).map(d => d.value + (d.visual ? ' ' + JSON.stringify(d.visual) : '')) })), shopifyFilters };
}

