  const j = await r.json();
  if (j.errors) return j.errors;
  const pk = {}, sk = {};
  for (const h of j.data.search.products.hits) {
    (h.customFields || []).forEach(c => (pk[c.key] ||= new Set()).add(c.value));
    (h.skus || []).forEach(s => (s.customFields || []).forEach(c => (sk[c.key] ||= new Set()).add(c.value)));
  }
  const f = o => Object.fromEntries(Object.entries(o).map(([k, v]) => [k, [...v].slice(0, 6)]));
  return { product: f(pk), sku: f(sk) };
}

