input.function:
async () => {
  const query = `query($q:String){ search(accountId:"shopify-35089973385", query:$q, products:{size:100, preFilter:[{not:[{field:"tags1", value:["hide"]}]}]}){ products { total hits { name tags1 customFields { key value } } } } }`;
  const j = await (await fetch('https://search.nosto.com/v1/graphql', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ query, variables: { q: 'dress' } }) })).json();
  const hits = j.data.search.products.hits;
  const vals = {}; let has = 0, multi = 0; const map = {};
  for (const h of hits) {
    const cp = h.customFields?.find(c => c.key === 'shopify-color-pattern');
    if (!cp) continue; has++;
    const ids = JSON.parse(cp.value); if (ids.length > 1) multi++;
    vals[cp.value] = (vals[cp.value] || 0) + 1;
    const tag = (h.tags1 || []).find(t => /^COLOR_/.test(t));
    if (ids.length === 1) (map[ids[0].split('/').pop()] ||= new Set()).add(tag || '(no tag)');
  }
  return { total: hits.length, withColorPattern: has, multiColour: multi, distinctFacetValues: Object.keys(vals).length,
    multiExamples: Object.keys(vals).filter(v => JSON.parse(v).length > 1).slice(0, 3),
    idToTag: Object.fromEntries(Object.entries(map).map(([k, v]) => [k, [...v]])) };
}

