import { useFacets, useProductFilters } from "@nosto/search-js/preact/hooks"
import { SearchStatsFacet, SearchTermsFacet } from "@nosto/nosto-js/client"
import { cl } from "@nosto/search-js/utils"
import { useCallback, useEffect, useRef } from "preact/hooks"
import { useFilterDrawer } from "@/shared/filters/FilterDrawerContext"
import ThemeIcon from "@/elements/ThemeIcon"
import ActiveFilters from "./ActiveFilters"
import SortGroup from "./SortGroup"
import TermsFacet from "./TermsFacet"
import RangeFacet from "./RangeFacet"
import DrawerButtons from "./DrawerButtons"
import { strings } from "@/lib/i18n"

/**
 * Slide-out filter drawer using the theme's markup (sections/search.liquid with filter_layout "slide-out",
 * snippets/collection-filters-sidebar.liquid), so collections.css / collection-bar.css style it.
 * Open state, scroll lock and Escape mirror the theme's collection.js. Render it inside `.collection__products`.
 * `showSort` adds the "Sort by" group: on the collection page sort lives in the drawer; on search it's in the bar.
 */
export default function FilterDrawer({ showSort = false }: { showSort?: boolean }) {
  const { facets } = useFacets()
  const { filters } = useProductFilters()
  const { isOpen, setOpen } = useFilterDrawer()
  const closeRef = useRef<HTMLButtonElement>(null)
  const text = strings()

  const close = useCallback(() => setOpen(false), [setOpen])

  useEffect(() => {
    if (!isOpen) return
    // Same events collection.js uses, so the theme locks page scroll
    document.dispatchEvent(new CustomEvent("theme:scroll:lock", { bubbles: true }))
    closeRef.current?.focus()

    function onKeyUp(e: KeyboardEvent) {
      if (e.key === "Escape") close()
    }
    document.addEventListener("keyup", onKeyUp)

    return () => {
      document.removeEventListener("keyup", onKeyUp)
      document.dispatchEvent(new CustomEvent("theme:scroll:unlock", { bubbles: true }))
    }
  }, [isOpen, close])

  if (!facets?.length) {
    return null
  }

  return (
    <>
      <div
        className={cl("collection__sidebar__slide-out", isOpen && "expanded drawer--animated")}
        id="NostoFilters"
        data-nosto-filters
        role="dialog"
        aria-modal="true"
        aria-label={text.filters}
        aria-hidden={!isOpen}
      >
        <div className="collection__sidebar__head">
          <h3>
            {text.filters}
            {filters.length > 0 && <span className="filter-count">{filters.length}</span>}
          </h3>
          <button
            type="button"
            className="collection__sidebar__close"
            aria-label={text.hideFilters}
            onClick={close}
            ref={closeRef}
          >
            <ThemeIcon name="cancel" />
          </button>
        </div>

        <div
          className={cl("collection__sidebar", filters.length > 0 && "collection__sidebar--has-buttons")}
          data-scroll-lock-scrollable
          style={{ "--swatch-size": "var(--swatch-size-filters)" }}
        >
          <ActiveFilters />
          <div className="collection__filters">
            {showSort && <SortGroup />}
            {facets.map(facet => {
              switch (facet.type) {
                case "terms":
                  return <TermsFacet key={facet.id} facet={facet as SearchTermsFacet} />
                case "stats":
                  return <RangeFacet key={facet.id} facet={facet as SearchStatsFacet} />
                default:
                  return null
              }
            })}
          </div>
        </div>

        <DrawerButtons onClose={close} />
      </div>
      {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions */}
      <span className="underlay" onClick={close} />
    </>
  )
}
import { useProductFilters } from "@nosto/search-js/preact/hooks"
import ThemeIcon from "@/elements/ThemeIcon"
import { strings } from "@/lib/i18n"

/**
 * Selected filter chips using the theme's markup (snippets/collection-filters-sidebar.liquid).
 */
export default function ActiveFilters() {
  const { filters: allFilters, removeAll } = useProductFilters()
  const filters = allFilters.filter(filter => filter !== undefined)

  if (!filters.length) {
    return null
  }

  return (
    <div className="collection__active__filters">
      {filters.length > 1 && (
        <button type="button" className="active__filters__clear" onClick={removeAll}>
          <small>{strings().clearFilters}</small>
        </button>
      )}
      {filters.map(filter => (
        <button
          type="button"
          key={`${filter.name}:${filter.value}`}
          className="active__filters__remove"
          aria-label={`Remove ${filter.name}: ${chipLabel(filter)}`}
          onClick={() => filter.remove()}
        >
          <small>{chipLabel(filter)}</small>
          <span className="filter__x">
            <ThemeIcon name="cancel" />
          </span>
        </button>
      ))}
    </div>
  )
}

/**
 * Price ranges come as "15 - 378"; show them like the slider labels ("$15 - $378").
 * The currency symbol is hardcoded: Nosto returns bare numbers and multi-currency is not yet set up on
 * the account, so non-USD markets will read wrong here. Revisit with the multi-market phase.
 */
function chipLabel({ field, value }: { field: string; value: string }) {
  return field === "price" ? value.replace(/\d+(\.\d+)?/g, amount => `$${amount}`) : value
}
import { useNostoAppState, useProductFilters } from "@nosto/search-js/preact/hooks"
import { plural, strings } from "@/lib/i18n"

type Props = {
  onClose: () => void
}

/**
 * Sticky Reset / "View N items" buttons at the bottom of the drawer (snippets/collection-filters-sidebar.liquid).
 */
export default function DrawerButtons({ onClose }: Props) {
  const { filters, removeAll } = useProductFilters()
  const total = useNostoAppState(state => state.response.products?.total ?? 0)
  const text = strings()

  return (
    <div className="collection__sidebar__buttons">
      {filters.length > 0 && (
        <button type="button" className="btn btn--primary btn--outline btn--full" onClick={removeAll}>
          <span>{text.reset}</span>
        </button>
      )}
      <button type="button" className="btn btn--primary btn--solid btn--full" onClick={onClose}>
        <span>{plural(total, text.viewItemsOne, text.viewItemsOther)}</span>
      </button>
    </div>
  )
}
import { useRange } from "@nosto/search-js/preact/hooks"
