// Run in page context: captures the filter drawer + toolbar state for live-vs-Nosto comparison
() => {
  const S = (el, props) => { if (!el) return null; const s = getComputedStyle(el); return Object.fromEntries(props.map(p => [p, s.getPropertyValue(p)])); };
  const R = el => { if (!el) return null; const b = el.getBoundingClientRect(); return [b.x, b.y, b.width, b.height].map(n => Math.round(n * 10) / 10); };
  const T = el => el?.textContent.trim().replace(/\s+/g, ' ') ?? null;
  const vis = el => el && el.getClientRects().length && getComputedStyle(el).visibility !== 'hidden';
  const font = ['font-family', 'font-size', 'font-weight', 'line-height', 'letter-spacing', 'text-transform', 'color'];
  const box = ['padding', 'margin', 'border', 'background-color'];
  const drawer = [...document.querySelectorAll('.collection__sidebar__slide-out')].find(vis) || document.querySelector('.collection__sidebar__slide-out');
  const q = sel => drawer?.querySelector(sel);
  const qa = sel => [...(drawer?.querySelectorAll(sel) || [])];
  const groups = qa('.filter-group, details[data-collapsible]').filter((g, i, a) => !a.some(o => o !== g && o.contains(g)));
  const priceGroup = groups.find(g => /price/i.test(T(g.querySelector('summary, .filter-group__heading, [data-collapsible-trigger]')) || ''));
  const firstItem = qa('.sidebar__item').find(vis);
  const chips = [...document.querySelectorAll('.active__filters__remove, .collection__active__filters a, .collection__active__filters button')].filter(vis);
  const clear = [...document.querySelectorAll('.active__filters__clear')].filter(vis);
  const btns = qa('.collection__sidebar__buttons .btn, .collection__sidebar__buttons a, .collection__sidebar__buttons button').filter(vis);
  const toolbarFilter = [...document.querySelectorAll('button, a')].find(e => vis(e) && /^filters?\b/i.test(T(e)) && !drawer?.contains(e));
  return {
    theme: Shopify.theme.id,
    url: location.pathname + location.search,
    title: document.title,
    toolbarFilter: toolbarFilter && { html: toolbarFilter.outerHTML.slice(0, 300), font: S(toolbarFilter, font), rect: R(toolbarFilter) },
    drawer: drawer && { open: vis(drawer) && R(drawer)[0] >= 0, cls: drawer.className, rect: R(drawer), bg: S(drawer, ['background-color']) },
    head: q('.collection__sidebar__head') && { html: q('.collection__sidebar__head').outerHTML.slice(0, 400), h: S(q('.collection__sidebar__head h3, .collection__sidebar__head h2, .collection__sidebar__head p'), font), rect: R(q('.collection__sidebar__head')) },
    groups: groups.map(g => { const h = g.querySelector('summary, .filter-group__heading, [data-collapsible-trigger]'); return { title: T(h)?.slice(0, 40), open: g.hasAttribute('open') ? g.getAttribute('open') : null, cls: g.className, hFont: S(h, font), hRect: R(h) }; }),
    price: priceGroup && { html: priceGroup.querySelector('.filter-group__content, [data-collapsible-body], [data-collapsible-content]')?.innerHTML.replace(/\s+/g, ' ').slice(0, 1500),
      inputs: [...priceGroup.querySelectorAll('input')].map(i => ({ type: i.type, name: i.name, value: i.value, ph: i.placeholder, min: i.min, max: i.max, font: S(i, ['font-size', 'color']), rect: R(i) })),
      texts: [...priceGroup.querySelectorAll('span, label, p')].filter(vis).map(T).filter(Boolean).slice(0, 12) },
    item: firstItem && { html: firstItem.outerHTML.replace(/\s+/g, ' ').slice(0, 500), font: S(firstItem.querySelector('label span, label'), font), rect: R(firstItem), checkbox: S(firstItem.querySelector('input'), ['width', 'height', 'appearance', 'border']), labelRect: R(firstItem.querySelector('label')) },
    more: (() => { const m = qa('.collection__sidebar__actions button, .collection__sidebar__actions a, .collection__sidebar__link').find(vis); return m && { html: m.outerHTML.slice(0, 300), font: S(m, font) }; })(),
    chips: chips.map(c => ({ where: drawer?.contains(c) ? 'drawer' : 'page', text: T(c), html: c.outerHTML.replace(/\s+/g, ' ').slice(0, 300), font: S(c.querySelector('small') || c, font), box: S(c, box), rect: R(c) })),
    clear: clear.map(c => ({ where: drawer?.contains(c) ? 'drawer' : 'page', text: T(c), html: c.outerHTML.replace(/\s+/g, ' ').slice(0, 300), font: S(c.querySelector('small') || c, font), box: S(c, box), rect: R(c) })),
    buttons: btns.map(b => ({ text: T(b), cls: b.className, font: S(b, font), box: S(b, box), rect: R(b) })),
    countText: T([...document.querySelectorAll('.collection__products-count, [class*=results-count], .search__caption, p')].find(e => vis(e) && /results? found/i.test(T(e))))
  };
}

