  await page.waitForTimeout(500);
  await page.locator('[data-nosto-filters] label', { hasText: /^Dresses$/ }).first().click();
  await page.waitForTimeout(2500);
  await page.locator('[data-nosto-filters] .filter-group', { hasText: 'Size' }).locator('.filter-group__heading, summary, [data-collapsible-trigger]').first().click();
  await page.waitForTimeout(500);
  await page.locator('[data-nosto-filters] label', { hasText: /^S$/ }).first().click();
  await page.waitForTimeout(2500);
  return { id: await page.evaluate(() => Shopify.theme.id), url: page.url() };
}

