async (page) => {
  await page.goto(`https://www.elietahari.com/search?q=dress&preview_theme_id=157927932041`);
  await page.waitForTimeout(5000);
  await page.evaluate(() => document.querySelectorAll('csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
  await page.locator('button.popout__toggle', { hasText: 'Filters' }).first().click();
  await page.waitForTimeout(1000);
  const dr = page.locator('.collection__sidebar__slide-out.expanded');
  await dr.locator('.filter-group', { hasText: 'Product type' }).locator('[data-collapsible-trigger], summary, .filter-group__heading').first().click();
  await page.waitForTimeout(600);
  await dr.locator('label', { hasText: /^\s*Dresses\s*$/ }).first().click();
  await page.waitForTimeout(4000);
  const dr2 = page.locator('.collection__sidebar__slide-out.expanded');
  const sizeGroup = dr2.locator('.filter-group', { hasText: 'Size' });
  if (!(await sizeGroup.locator('label', { hasText: /^\s*S \(4-6\)\s*$/ }).first().isVisible())) await sizeGroup.locator('[data-collapsible-trigger], summary, .filter-group__heading').first().click();
  await page.waitForTimeout(600);
  await sizeGroup.locator('label', { hasText: /^\s*S \(4-6\)\s*$/ }).first().click();
  await page.waitForTimeout(4000);
  return { id: await page.evaluate(() => Shopify.theme.id), url: page.url(), drawerOpen: await page.locator('.collection__sidebar__slide-out.expanded').count() };
}

