async (page) => {
  const snap = () => page.evaluate(() => {
    const S = (el, props) => { if (!el) return null; const s = getComputedStyle(el); return Object.fromEntries(props.map(p => [p, s.getPropertyValue(p)])); };
    const R = el => { if (!el) return null; const b = el.getBoundingClientRect(); return [b.x, b.y, b.width, b.height].map(n => Math.round(n * 10) / 10); };
    const T = el => el?.textContent.trim().replace(/\s+/g, ' ') ?? null;
    const vis = el => el && el.getClientRects().length && getComputedStyle(el).visibility !== 'hidden' && R(el)[0] >= 0;
    const font = ['font-family', 'font-size', 'font-weight', 'line-height', 'letter-spacing', 'text-transform', 'color', 'text-decoration-line'];
    const box = ['padding', 'margin', 'border', 'border-radius', 'background-color', 'display', 'gap'];
    const drawer = document.querySelector('.collection__sidebar__slide-out.expanded');
    const where = e => drawer?.contains(e) ? 'drawer' : 'page';
    const el = (e) => ({ where: where(e), text: T(e), html: e.outerHTML.replace(/\s+/g, ' ').slice(0, 400), font: S(e.querySelector('small') || e, font), box: S(e, box), rect: R(e) });
    const wrap = [...document.querySelectorAll('.collection__active__filters')].filter(vis);
    return {
      theme: Shopify.theme.id, drawerOpen: !!drawer,
      headCount: drawer && { html: drawer.querySelector('.collection__sidebar__head h3')?.outerHTML.replace(/\s+/g, ' '), count: S(drawer.querySelector('.filter-count'), [...font, ...box]) },
      activeWrap: wrap.map(w => ({ where: where(w), rect: R(w), box: S(w, box) })),
      chips: [...document.querySelectorAll('.active__filters__remove')].filter(vis).map(el),
      clear: [...document.querySelectorAll('.active__filters__clear')].filter(vis).map(el),
      buttons: [...document.querySelectorAll('.collection__sidebar__buttons .btn')].filter(vis).map(el),
      selectedRow: (() => { const li = drawer?.querySelector('.sidebar__item--active'); return li && { html: li.outerHTML.replace(/\s+/g, ' ').slice(0, 300), font: S(li.querySelector('label span') || li.querySelector('label'), font) }; })(),
      groupHeadingWithSelection: (() => { const h = [...(drawer?.querySelectorAll('.filter-group__heading, summary, [data-collapsible-trigger]') || [])].find(x => /\(\d\)/.test(T(x))); return h && { text: T(h), html: h.outerHTML.replace(/\s+/g, ' ').slice(0, 300) }; })(),
      toolbar: [...document.querySelectorAll('.popout__toggle')].filter(vis).map(b => T(b))
    };
  });
  await page.screenshot({ path: '.playwright-mcp/qa/live-filters-selected-open.png' });
  const open = await snap();
  await page.keyboard.press('Escape');
  await page.waitForTimeout(1200);
  await page.screenshot({ path: '.playwright-mcp/qa/live-filters-selected-closed.png' });
  const closed = await snap();
  return { open, closed };
}

