input.code:
async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto(`https://www.elietahari.com/search?q=dress&preview_theme_id=157927932041`);
  await page.waitForTimeout(5000);
  await page.evaluate(() => { document.querySelectorAll('csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'); window.__marker = 1; });
  const state = (label) => page.evaluate((label) => {
    const d = document.querySelector('.collection__sidebar__slide-out');
    const groups = [...(d?.querySelectorAll('.filter-group') || [])].map(g => {
      const h = g.querySelector('[data-collapsible-trigger], summary');
      const body = g.querySelector('[data-collapsible-body], .filter-group__content');
      return { title: h?.textContent.trim().replace(/\s+/g, ' ').slice(0, 25), openAttr: g.getAttribute('open') ?? g.querySelector('[open]')?.getAttribute('open') ?? null, bodyH: body ? Math.round(body.getBoundingClientRect().height) : null };
    });
    return { label, theme: Shopify.theme.id, url: location.search, sameDocument: window.__marker === 1, drawerOpen: d?.classList.contains('expanded'),
      loading: [...document.querySelectorAll('.is-loading, [class*=loading]')].filter(e => e.getClientRects().length).map(e => e.className).slice(0, 3),
      groups, chips: [...(d?.querySelectorAll('.active__filters__remove') || [])].map(c => c.textContent.trim()),
      count: document.querySelector('.collection__sidebar__buttons .btn--solid')?.textContent.trim(), scrollY };
