import type { GridTile } from "@/lib/themeSettings"

/**
 * Places tiles (editorial images) among the products of the current page. Tile positions are 1-based slots
 * in the whole grid, counting products and tiles, like collection.liquid: a tile at position 5 is the 5th
 * item in the grid. `from` is the offset of the first product shown; with "Load more" / infinite scroll it
 * stays 0 and `count` grows. Tiles past the last product go after it on the last page.
 *
 * Returns, per product on the page, the tiles to render before it, plus the tiles to render at the end.
 */
export function placeTiles<T extends Pick<GridTile, "position">>(
  tiles: T[],
  from: number,
  count: number,
  total: number
) {
  const sorted = [...tiles].sort((a, b) => a.position - b.position)
  const before: T[][] = Array.from({ length: count }, () => [])
  let slot = 0
  let next = 0

  for (let product = 0; product < from + count; product++) {
    while (next < sorted.length && sorted[next].position <= slot + 1) {
      slot++
      if (product >= from) before[product - from].push(sorted[next])
      next++
    }
    slot++
  }

  const after = from + count >= total ? sorted.slice(next) : []
  return { before, after }
}

