content.content:
  if (product.tags1?.includes("skeleton")) {
    return <Skeleton />
  }

  if (!product.handle) {
    return null
  }

  const Element = context === "autocomplete" ? AutocompleteElement : SerpElement

  return (
    <div className="ns-card-cell">
      <Element
        as={DynamicCard}
        hit={{
          productId: product.productId!,
          url: product.url
        }}
        componentProps={{
          handle: product.handle,
          section: cardSections[type],
          lazy: true,
          mock: mockThemeCards
        }}
      />
      {!mockThemeCards && <Skeleton />}
    </div>
  )
}

/**
 * Mirrors the outer markup of product-grid-item.liquid so theme.css sizes it like the real card:
 * image box, then title, price and the colour count.
 */
function GridSkeleton() {
  return (
    <div className="grid-item product-item product-item--left product-item--outer-text ns-skeleton" aria-hidden="true">
      <div className="product-item__image">
        <div className="ns-shimmer ns-skeleton-image" />
      </div>
      <div className="product-information">

