<collection-component
  class="page search-page collection section-padding {{ color_scheme }}"
  data-section-type="collection"
  data-section-id="{{ section.id }}"
  data-sort="{{ enable_sort }}"
>
  {%- render 'search-form' -%}

  {%- if settings.rs_nosto_search_enabled -%}
    {%- comment -%}
      Nosto search (template code: roswell-studios/Elie_Tahari_TAHARI_Nosto) portals its results into the
      mount that rs-nosto-results renders. Products only: Shopify's page and article results are
      intentionally not shown. The <template> hands Nosto the theme's Model | Product switcher markup —
      it sits outside the mount because Nosto clears the mount on first render.
    {%- endcomment -%}
    <template data-nosto-model-switcher>
      {%- render 'collection-model-switcher' -%}
    </template>

    {%- render 'rs-nosto-results',
      mount: 'search',
      pagination: settings.rs_nosto_search_pagination,
      columns_desktop: settings.rs_nosto_search_columns_desktop,
      columns_mobile: settings.rs_nosto_search_columns_mobile,
      card_image_mode: section.settings.card_image_mode,
      enable_sort: enable_sort,
      enable_filters: enable_filters
    -%}
  {%- elsif search.performed -%}
    {%- capture search_results -%}
      {%- paginate search.results by 36 -%}
        {%- render 'product-grid-scripts' -%}

        <div class="grid-outer" data-products-grid>
          <div class="grid" id="SearchLoop">
            {%- if search.results == empty -%}
      {{ search_results }}
    </div>
  {%- endif -%}
</collection-component>

<script src="{{ 'collection-model-switcher.js' | asset_url }}" defer="defer"></script>

{%- comment -%} Not in Nosto mode: collection-filters-form's popstate handler would fight Nosto's URL state. {%- endcomment -%}
{%- unless settings.rs_nosto_search_enabled -%}
  {%- if search.performed and enable_sort or enable_filters -%}
    <script src="{{ 'collection.js' | asset_url }}" defer="defer"></script>
    <script src="{{ 'collection-filters-form.js' | asset_url }}" defer="defer"></script>
  {%- endif -%}
{%- endunless -%}

{%- if settings.quickview_enable -%}
  <script src="{{ 'product-info.js' | asset_url }}" defer="defer"></script>
{%- endif -%}

{%- if show_recently_viewed_indicator -%}
  <script src="{{ 'grid-item.js' | asset_url }}" defer></script>
