{%- comment -%}
  Theme copy for the Nosto search UI (roswell-studios/Elie_Tahari_TAHARI_Nosto reads [data-nosto-i18n]),
  so Nosto renders the same translated strings as the Liquid search page and predictive search.
  {terms} and {count} are filled in by Nosto. Rendered from header-search-popdown.liquid when
  rs_nosto_search_enabled is on, so it is on every page; Nosto reads the first copy.
{%- endcomment -%}
{%- comment -%}
  A literal {terms} placeholder can't sit inside a {{ }} output tag: Shopify's Liquid parser reads the
  closing brace as the end of the tag and rejects the file on upload (theme check does not catch this).
  Build every placeholder string here instead, then output the variable.
{%- endcomment -%}
{%- liquid
  assign rs_terms = '{terms}'
  assign rs_results_one = 'general.search.results_with_count_and_term' | t: count: 1, terms: rs_terms | replace_first: '1', '{count}'
  assign rs_results_other = 'general.search.results_with_count_and_term' | t: count: 2, terms: rs_terms | replace_first: '2', '{count}'
  assign rs_no_results = 'general.search.no_results' | t: terms: rs_terms
  assign rs_search_for = 'general.search.search_for' | t: terms: rs_terms
-%}
<script type="application/json" data-nosto-i18n>
  {
    "resultsOne": {{ rs_results_one | json }},
    "resultsOther": {{ rs_results_other | json }},
    "noResults": {{ rs_no_results | json }},
    "noMatches": {{ 'collections.general.no_matches' | t | json }},
    "filters": {{ 'collections.general.filters' | t | json }},
    "sort": {{ 'collections.general.sort' | t | json }},
    "prev": {{ 'general.pagination.prev' | t | json }},
    "next": {{ 'general.pagination.next' | t | json }},
    "products": {{ 'general.search.products' | t | json }},
    "suggestions": {{ 'general.search.suggestions' | t | json }},
    "searchFor": {{ rs_search_for | json }},
    "sortOptions": {
      {%- for option in search.sort_options -%}
        {{ option.value | json }}: {{ option.name | json }}{% unless forloop.last %},{% endunless %}
      {%- endfor -%}
    }
  }
</script>
