import { useState } from "preact/hooks"
import { useProductFilters } from "@nosto/search-js/preact/hooks"
import PaginatedProducts from "@/shared/pagination/PaginatedProducts"
import ProductGrid from "@/shared/ProductGrid"
import { ContentChildrenProps, wrapContent } from "@/shared/ContentWrapper"
import NoResults from "@/shared/NoResults"
import { getEditorialTiles } from "@/lib/themeSettings"
import PlpToolbar from "./PlpToolbar"

/**
 * Collection page (sections/collection.liquid): PLP bar, filter drawer with sort, and the product grid with the
 * collection's editorial tiles ("RS: Metaobject-driven editorial images").
 */
function PlpPage({ foundProducts, loading }: ContentChildrenProps) {
  const tiles = useEditorialTiles()

  if (!foundProducts && !loading) return <NoResults />
  return (
    <>
      <PlpToolbar />
      <ProductGrid loading={loading} sortInDrawer>
        <PaginatedProducts tiles={tiles} />
      </ProductGrid>
    </>
  )
}

/** Like the theme, editorial tiles only show on the unfiltered collection */
function useEditorialTiles() {
  const [tiles] = useState(getEditorialTiles)
  const { filters } = useProductFilters()
  return filters.length > 0 ? [] : tiles
}

export default wrapContent("category", PlpPage)

