import { ContentChildrenProps, wrapContent } from "@/shared/ContentWrapper"
import { useNostoAppState } from "@nosto/search-js/preact/hooks"
import NoResults from "@/shared/NoResults"
import ProductGrid from "@/shared/ProductGrid"
import { format, plural, strings } from "@/lib/i18n"

/**
 * Search page layout mirrors sections/search.liquid: caption, collection nav, then the products grid.
 */
function SearchPage({ foundProducts, loading }: ContentChildrenProps) {
  if (!foundProducts && !loading) return <NoResults />
  return (
    <>
      <ResultsCount />
      <SearchToolbar />
      <ProductGrid loading={loading}>
        <PaginatedProducts />
      </ProductGrid>
    </>
  )
}

/**
 * Blank until results for the current query arrive (skeleton or new search), so it never shows a stale count.
 * Loading more pages, sorting or filtering keep the count in place.
 */
function ResultsCount() {
  const { total, query, current } = useNostoAppState(state => ({
    total: state.response.products?.total ?? 0,
    query: state.response.query,
    current: !!state.response.query && state.response.query === state.query?.query
  }))

  const text = strings()

  return (
    <p className="search__caption caps" data-results-count data-nosto-element="totalResults">
      {current ? format(plural(total, text.resultsOne, text.resultsOther), { terms: query ?? "" }) : "\u00a0"}
    </p>
  )
}

export default wrapContent("search", SearchPage)
