      aria-label={strings().sortAndFilters}
      className={cl(
        "collection__nav",
        sortEnabled && "collection__nav--sort",
        showFilters && "collection__nav--filter"
      )}
      data-collection-nav
    >
      {showFilters && (
        <div className="popout--group">
          <FilterButton />
        </div>
      )}
      {sortEnabled && <SortPopout />}
      <ThemeModelSwitcher />
    </nav>
  )
}
