input.function:
async () => {
  const q = (products) => fetch('https://search.nosto.com/v1/graphql', { method: 'POST', headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ query: `query($p: InputSearchProducts){ search(accountId:"shopify-35089973385", products:$p){ products { total categoryId categoryPath hits { name } facets { ... on SearchTermsFacet { name } ... on SearchStatsFacet { name } } } } }`, variables: { p: products } }) }).then(r => r.json());
  const byId = await q({ categoryId: "180839874697", size: 3 });
  const byPath = await q({ categoryPath: "Dresses & Jumpsuits", size: 3 });
  const both = await q({ categoryId: "180839874697", categoryPath: "Dresses & Jumpsuits", size: 3, preFilter: [{ not: [{ field: "tags1", value: ["hide"] }] }] });
  const s = r => r.errors ? r.errors[0].message : { total: r.data.search.products.total, id: r.data.search.products.categoryId, path: r.data.search.products.categoryPath, first: r.data.search.products.hits.map(h => h.name), facets: r.data.search.products.facets?.map(f => f.name) };
  const live = document.querySelector('.collection__products-count, [data-collection-count]')?.textContent?.trim();
  return { byId: s(byId), byPath: s(byPath), bothWithHide: s(both), shopifyGridItems: document.querySelectorAll('[data-products-grid] .product-item').length };
}

