import { createContext } from "preact"
import { useCallback, useContext, useMemo, useState } from "preact/hooks"
import { ComponentChildren } from "preact"

type FocusedGroup = {
  /** Handleized group name, matching `data-filter-label` (e.g. "necklace-length") */
  label: string
  /** Changes on every request, so asking for the same group twice still opens it */
  key: number
}

type FilterDrawerContextType = {
  isOpen: boolean
  setOpen: (open: boolean) => void
  toggle: () => void
  focusedGroup: FocusedGroup | null
  /** Opens the drawer with one group expanded and the others collapsed (PLP shortcut filters) */
  focusGroup: (label: string) => void
}

const FilterDrawerContext = createContext<FilterDrawerContextType | undefined>(undefined)

type FilterDrawerProviderProps = {
  children: ComponentChildren
  initialOpen?: boolean
}

export function FilterDrawerProvider({ children, initialOpen = false }: FilterDrawerProviderProps) {
  const [isOpen, setOpen] = useState(initialOpen)
  const [focusedGroup, setFocusedGroup] = useState<FocusedGroup | null>(null)

  const toggle = useCallback(() => setOpen(open => !open), [])
  const focusGroup = useCallback((label: string) => {
    setFocusedGroup(previous => ({ label, key: (previous?.key ?? 0) + 1 }))
    setOpen(true)
  }, [])

  const contextValue = useMemo(
    () => ({ isOpen, setOpen, toggle, focusedGroup, focusGroup }),
    [isOpen, toggle, focusedGroup, focusGroup]
  )

  return <FilterDrawerContext.Provider value={contextValue}>{children}</FilterDrawerContext.Provider>
}

export function useFilterDrawer() {
  const context = useContext(FilterDrawerContext)
  if (context === undefined) {
    throw new Error("useFilterDrawer must be used within a FilterDrawerProvider")
  }
  return context
}
