content.content:
{%- if settings.rs_nosto_collection_enabled -%}
  {%- comment -%}
    Nosto collection page (template code: roswell-studios/Elie_Tahari_TAHARI_Nosto) portals its toolbar, filter
    drawer and grid into the mount that rs-nosto-results renders. Nosto identifies the collection from its own
    page tagging. Pagination, columns and products per page come from "RS: Nosto Settings" (defaults match this
    section on the live theme); medium columns follow this section's rule. The <template> hands Nosto the
    Model | Product switcher markup — it sits outside the mount because Nosto clears the mount on first render.
  {%- endcomment -%}
  <collection-component
    class="collection collection-products collection-{{ collection.handle }} section-padding {{ color_scheme }}"
    id="Collection--{{ section.id }}"
    data-section-id="{{ section.id }}"
    data-section-type="collection"
    data-sort="{{ enable_sort }}"
    data-collection="{{ collection.url | default: '/collections/all' }}"
  >
    <template data-nosto-model-switcher>
      {%- render 'collection-model-switcher' -%}
    </template>

    {%- comment -%} The header renders it when Nosto search is on {%- endcomment -%}
    {%- unless settings.rs_nosto_search_enabled -%}
      {%- render 'nosto-i18n' -%}
    {%- endunless -%}

    {%- liquid
      assign rs_columns_desktop = settings.rs_nosto_collection_columns_desktop
      assign rs_columns_medium = 3
      if rs_columns_desktop == 2 or rs_columns_desktop == 4
        assign rs_columns_medium = 2
      endif

      render 'rs-nosto-results', mount: 'collection', pagination: settings.rs_nosto_collection_pagination, columns_desktop: rs_columns_desktop, columns_medium: rs_columns_medium, columns_mobile: settings.rs_nosto_collection_columns_mobile, page_size: settings.rs_nosto_collection_products_per_page, card_image_mode: section.settings.card_image_mode, enable_sort: enable_sort, enable_filters: enable_filters
    -%}
  </collection-component>

  <script src="{{ 'collection-model-switcher.js' | asset_url }}" defer="defer"></script>

  {%- comment -%}
    Not in Nosto mode: collection.js / collection-filters-form.js (their popstate handler would fight Nosto's URL
    state) and rs-infinite-scroll.js (Nosto paginates).
  {%- endcomment -%}
  {%- if settings.quickview_enable -%}
    <script src="{{ 'product-info.js' | asset_url }}" defer="defer"></script>
  {%- endif -%}

  {%- if show_recently_viewed_indicator -%}
    <script src="{{ 'grid-item.js' | asset_url }}" defer></script>
  {%- endif -%}
{%- else -%}
{%- paginate collection.products by product_limit -%}
  {%- assign featured_images_array = '' -%}
