async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  const grab = () => page.evaluate(() => {
    const T = e => e?.textContent.trim().replace(/\s+/g, ' ');
    const R = e => { if (!e) return null; const b = e.getBoundingClientRect(); return [b.x, b.y, b.width, b.height].map(Math.round); };
    const grid = [...document.querySelectorAll('[data-products-grid] .grid, [data-nosto-collection] .grid')].find(g => g.offsetParent);
    const cards = grid ? [...grid.children].filter(c => c.offsetParent) : [];
    const nav = document.querySelector('.collection__nav');
    const mount = document.querySelector('[data-nosto-collection]');
    return { theme: Shopify.theme.id, mount: mount && { ...mount.dataset }, wrapperStyle: mount?.parentElement?.getAttribute('style'),
      nav: nav && { html: nav.outerHTML.replace(/\s+/g, ' ').slice(0, 200), rect: R(nav), items: [...nav.children].map(c => T(c).slice(0, 40)) },
      grid: grid && { cols: getComputedStyle(grid).gridTemplateColumns, gap: getComputedStyle(grid).gap, rect: R(grid) },
      cards: cards.length, firstCard: R(cards[0]), firstTitles: cards.slice(0, 4).map(c => T(c.querySelector('.product-item__title'))),
      pagination: [...document.querySelectorAll('.pagination, [class*=pagination]')].filter(e => e.offsetParent).map(e => e.className).slice(0, 3),
      i18nSort: (() => { try { return Object.keys(JSON.parse(document.querySelector('[data-nosto-i18n]').textContent).sortOptions); } catch { return null; } })(),
      sortText: T(document.querySelector('.popout--sort .popout__toggle')) };
  });
  const out = {};
  for (const [label, url] of [['live', 'https://www.elietahari.com/collections/dresses?preview_theme_id=157927932041'], ['dev', 'https://www.elietahari.com/collections/dresses?preview_theme_id=158466539657&nostodebug=true']]) {
    await page.goto(url);
    await page.waitForTimeout(8000);
    await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
    await page.screenshot({ path: `.playwright-mcp/qa/${label}-plp-dresses-1440.png` });
    out[label] = await grab();
  }
  return out;
}

