python3 - <<'EOF'
p='src/shared/toolbar/SortPopout.tsx'; s=open(p).read()
s=s.replace('import { useSort } from "@nosto/search-js/preact/hooks"','import { useNostoAppState, useSort } from "@nosto/search-js/preact/hooks"',1)
s=s.replace('import { strings } from "@/lib/i18n"','import { strings } from "@/lib/i18n"\nimport { tagging } from "@/lib/tagging"',1)
old="""  const { activeSort, setSort } = useSort(sortOptions)
  const [open, setOpen] = useState(false)
  const popoutRef = useRef<HTMLDivElement>(null)
  const active = sortOptions.find(option => option.id === activeSort)"""
new="""  const { activeSort, setSort } = useSort(sortOptions)
  const [open, setOpen] = useState(false)
  const popoutRef = useRef<HTMLDivElement>(null)
  // Like the theme: search always names its sort (Shopify's search.sort_by defaults to relevance), but a
  // collection's sort_by is blank until the shopper picks one, so the button reads just "Sort"
  const sortChosen = useNostoAppState(state => !!state.query.products?.sort?.length)
  const showActive = sortChosen || tagging.pageType() !== "category"
  const active = showActive ? sortOptions.find(option => option.id === activeSort) : undefined"""
assert old in s; s=s.replace(old,new,1); open(p,'w').write(s)
EOF
