async (page) => {
  const sortText = () => page.evaluate(() => ({ theme: Shopify.theme.id, text: [...document.querySelectorAll('.popout--sort .popout__toggle__text')].filter(e => e.offsetParent && getComputedStyle(e).display !== 'none').map(e => e.textContent.trim()), active: document.querySelector('.popout--sort .popout')?.classList.contains('is-active') }));
  const out = {};
  await page.goto('https://www.elietahari.com/collections/dresses?preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(8000);
  out.collectionDefault = await sortText();
  await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
  await page.locator('.popout--sort .popout__toggle').first().click();
  await page.waitForTimeout(500);
  await page.locator('.popout-list__option', { hasText: /low to high/i }).first().click();
  await page.waitForTimeout(3000);
  out.collectionChosen = { ...(await sortText()), url: page.url() };
  await page.goto('https://www.elietahari.com/collections/dresses?preview_theme_id=157927932041');
  await page.waitForTimeout(5000);
  out.liveCollectionDefault = await sortText();
  await page.goto('https://www.elietahari.com/search?q=dress&preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(8000);
  out.searchDefault = await sortText();
  return out;
}

