import { useSelectedFiltersCount } from "@nosto/search-js/preact/hooks"
import { useFilterDrawer } from "@/shared/filters/FilterDrawerContext"
import { strings } from "@/lib/i18n"

type Props = {
  /** Defaults to the theme's "Filters"; the collection page passes its own label */
  label?: string
}

/**
 * Opens the filter drawer (theme `.popout__toggle`). The page's bar wraps it in its `.popout--group`.
 */
export default function FilterButton({ label = strings().filters }: Props) {
  const { isOpen, toggle } = useFilterDrawer()
  const selectedFiltersCount = useSelectedFiltersCount()

  return (
    <button
      type="button"
      className="popout__toggle"
      aria-expanded={isOpen}
      aria-controls="NostoFilters"
      onClick={toggle}
    >
      {label}
      {selectedFiltersCount > 0 && <span className="filter-count">{selectedFiltersCount}</span>}
    </button>
  )
}
