async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.elietahari.com/search?q=dress&filter.productType=Dresses&filter.skus.customFields.size=S&preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(8000);
  const measure = () => page.evaluate(() => {
    const m = sel => { const e = document.querySelector(sel); if (!e) return null; const s = getComputedStyle(e.querySelector('small') || e); return { lh: s.lineHeight, h: Math.round(e.getBoundingClientRect().height * 10) / 10, ownLh: getComputedStyle(e).lineHeight }; };
    return { theme: Shopify.theme.id, chip: m('[data-nosto-filters] .active__filters__remove'), clear: m('[data-nosto-filters] .active__filters__clear'), more: m('[data-nosto-filters] .collection__sidebar__link') };
  });
  const before = await measure();
  await page.addStyleTag({ content: '[data-nosto-filters] .active__filters__remove, [data-nosto-filters] .active__filters__clear, [data-nosto-filters] .collection__sidebar__link { line-height: inherit; }' });
  const after = await measure();
  return { before, after };
}

