input.code:
async (page) => {
  await page.goto('https://www.elietahari.com/search?q=dress&filter.productType=Dresses&filter.skus.customFields.size=S&preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(9000);
  await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
  await page.locator('button.popout__toggle', { hasText: /^Filters/ }).filter({ visible: true }).first().click();
  await page.waitForTimeout(1000);
  await page.locator('[data-nosto-filters] .filter-group', { hasText: 'Price' }).locator('summary').first().click();
  await page.waitForTimeout(800);
  return await page.evaluate(() => {
    const h = sel => { const e = document.querySelector(sel); return e && Math.round(e.getBoundingClientRect().height * 10) / 10; };
    return { theme: Shopify.theme.id,
      toolbarButton: [...document.querySelectorAll('button.popout__toggle')].find(b => /filters/i.test(b.textContent)).outerHTML,
      chipH: h('[data-nosto-filters] .active__filters__remove'), clearH: h('[data-nosto-filters] .active__filters__clear'),
      moreLh: (() => { const e = document.querySelector('[data-nosto-filters] .collection__sidebar__link'); return e && getComputedStyle(e).lineHeight; })(),
      priceValues: [...document.querySelectorAll('.ns-range-values span')].map(s => s.textContent) };
  });
}

