async (page) => {
  const out = {};
  for (const [label, url] of [['searchDress', 'https://www.elietahari.com/search?q=dress&sort_by=price-descending&preview_theme_id=157927932041'], ['collectionDresses', 'https://www.elietahari.com/collections/dresses?sort_by=price-descending&preview_theme_id=157927932041'], ['searchDressFiltered', 'https://www.elietahari.com/search?q=dress&filter.p.product_type=Dresses&sort_by=price-descending&preview_theme_id=157927932041']]) {
    await page.goto(url);
    await page.waitForTimeout(4000);
    out[label] = await page.evaluate(() => {
      const slider = document.querySelector('[data-range-slider]');
      const prices = [...document.querySelectorAll('[data-products-grid] .product-item .price')].slice(0, 3).map(p => p.textContent.trim().replace(/\s+/g, ' '));
      return { theme: Shopify.theme.id, max: slider?.dataset.seMax, min: slider?.dataset.seMin, maxValue: slider?.dataset.seMaxValue, topPrices: prices };
    });
  }
  return out;
}

