import { useRef, useState } from "preact/hooks"

export type Range = [number, number]

type Props = {
  min: number
  max: number
  value: Range
  /** Called once a drag or key press ends */
  onChange: (value: Range) => void
  label: string
}

/** Width of a `.range__dot` in collection-bar.css */
const dotSize = 36

/**
 * Two-handle range slider using the theme's `range-slider` markup and geometry (assets/range-slider.js), so
 * collection-bar.css styles it. The theme custom element can't be rendered through JSX, so the dragging lives here.
 */
export default function ThemeRange({ min, max, value, onChange, label }: Props) {
  const trackRef = useRef<HTMLDivElement>(null)
  const [dragValue, setDragValue] = useState<Range | null>(null)
  const [low, high] = dragValue ?? value
  const span = max - min || 1

  function percent(v: number) {
    return (v - min) / span
  }

  function valueAt(clientX: number) {
    const rect = trackRef.current!.getBoundingClientRect()
    const ratio = Math.min(1, Math.max(0, (clientX - rect.left - dotSize / 2) / (rect.width - dotSize)))
    return Math.round(min + ratio * span)
  }

  function withHandle(handle: 0 | 1, v: number, current: Range): Range {
    return handle === 0 ? [Math.min(v, current[1]), current[1]] : [current[0], Math.max(v, current[0])]
  }

