  function onPointerDown(handle: 0 | 1, e: PointerEvent) {
    e.preventDefault()
    let current: Range = [low, high]

    function onMove(event: PointerEvent) {
      current = withHandle(handle, valueAt(event.clientX), current)
      setDragValue(current)
    }

    function onUp() {
      document.removeEventListener("pointermove", onMove)
      document.removeEventListener("pointerup", onUp)
      setDragValue(null)
      onChange(current)
    }

    document.addEventListener("pointermove", onMove)
    document.addEventListener("pointerup", onUp)
  }

  function onKeyDown(handle: 0 | 1, e: KeyboardEvent) {
    const step = Math.max(1, Math.round(span / 100))
    const delta = { ArrowLeft: -step, ArrowDown: -step, ArrowRight: step, ArrowUp: step }[e.key]
    if (!delta) return
    e.preventDefault()
    const current: Range = [low, high]
    const next = Math.min(max, Math.max(min, current[handle] + delta))
    onChange(withHandle(handle, next, current))
  }

  // A render helper rather than a component, so the dots keep focus across re-renders
  function renderDot(handle: 0 | 1) {
    const v = handle === 0 ? low : high
    return (
      <div
        className={`range__dot range__dot--${handle === 0 ? "left" : "right"}`}
        style={{ left: `calc(${percent(v)} * (100% - ${dotSize}px))`, touchAction: "none" }}
        role="slider"
        tabIndex={0}
        aria-label={`${label} ${handle === 0 ? "minimum" : "maximum"}`}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuenow={v}
        onPointerDown={e => onPointerDown(handle, e)}
        onKeyDown={e => onKeyDown(handle, e)}
      >
        <span>&nbsp;</span>
      </div>
    )
  }

  // The line is 18px narrower than the track (8px inset each side plus its 1px border), so its % maps to the dot travel
  const lineOffset = `calc(${percent(low)} * (100% - 18px))`
  const lineWidth = `calc(${percent(high) - percent(low)} * (100% - 18px))`

  return (
    <div className="filter__price__range range is-initialized" ref={trackRef}>
      {renderDot(0)}
      {renderDot(1)}
      <div className="range__line">
        <span style={{ marginLeft: lineOffset, width: lineWidth }}>&nbsp;</span>
      </div>
    </div>
  )
}
