import { fireEvent, render } from "@testing-library/preact"
import { describe, expect, it, vi } from "vitest"
import ThemeRange from "@/elements/ThemeRange"

function renderRange(value: [number, number] = [25, 75]) {
  const onChange = vi.fn()
  const { container } = render(<ThemeRange min={0} max={100} value={value} onChange={onChange} label="Price" />)
  const [low, high] = Array.from(container.querySelectorAll<HTMLElement>('[role="slider"]'))
  const track = container.querySelector<HTMLElement>(".range")!
  return { onChange, low, high, track }
}

describe("ThemeRange", () => {
  it("renders the theme range markup with both handles", () => {
    const { low, high, track } = renderRange()
    expect(track.classList.contains("is-initialized")).toBe(true)
    expect(low.classList.contains("range__dot--left")).toBe(true)
    expect(low.getAttribute("aria-valuenow")).toBe("25")
    expect(high.getAttribute("aria-valuenow")).toBe("75")
  })

  it("moves a handle with the arrow keys", () => {
    const { onChange, low, high } = renderRange()
    fireEvent.keyDown(low, { key: "ArrowRight" })
    expect(onChange).toHaveBeenLastCalledWith([26, 75])
    fireEvent.keyDown(high, { key: "ArrowLeft" })
    expect(onChange).toHaveBeenLastCalledWith([25, 74])
  })

  it("keeps the handles from crossing", () => {
    const { onChange, low } = renderRange([50, 50])
    fireEvent.keyDown(low, { key: "ArrowRight" })
    expect(onChange).toHaveBeenLastCalledWith([50, 50])
  })

  it("commits the dragged value on release", () => {
    const { onChange, high, track } = renderRange()
    // 136px track: 36px dot leaves 100px of travel, so 1px = 1 unit
    track.getBoundingClientRect = () => ({ left: 0, width: 136 }) as DOMRect
    fireEvent.pointerDown(high)

