import { useRange } from "@nosto/search-js/preact/hooks"
import { SearchStatsFacet } from "@nosto/nosto-js/client"
import { useState } from "preact/hooks"
import ThemeRange, { Range } from "@/elements/ThemeRange"
import FilterGroup from "@/shared/filters/FilterGroup"
import { isPriceField } from "@/lib/utils"
import { strings } from "@/lib/i18n"

type Props = {
  facet: SearchStatsFacet
}

/**
 * Range facet (e.g. Price) using the theme's price filter markup (snippets/filters.liquid, price_range): slider plus
 * From / To inputs. Like the theme, a price slider starts at 0 and ends at the highest price in the results.
 */
export default function RangeFacet({ facet }: Props) {
  const { min, max, range, updateRange } = useRange(facet.id)
  const [dragged, setDragged] = useState<Range | null>(null)
  const isPrice = isPriceField(facet.field)
  const low = isPrice ? 0 : Math.floor(min)
  const high = Math.ceil(max)
  const value: Range = [Math.floor(range[0] ?? low), Math.ceil(range[1] ?? high)]
  const isSelected = value[0] > low || value[1] < high
  const text = strings()

  function onChange([from, to]: Range) {
    setDragged(null)
    // Selecting the full range clears the filter
    updateRange([from > low ? from : undefined, to < high ? to : undefined])
  }

  function onField(handle: 0 | 1, input: string) {
    const number = Math.round(Number(input))
    const next: Range = [...value]
    next[handle] = input === "" || Number.isNaN(number) ? (handle === 0 ? low : high) : number
    next[handle] = Math.min(high, Math.max(low, next[handle]))
    onChange(next[0] > next[1] ? [next[1], next[0]] : next)
  }

  // Like the theme, an input shows a value only while that end is filtered or being dragged; otherwise its placeholder
  const shown = (handle: 0 | 1) => (dragged ? String(dragged[handle]) : range[handle] != null ? String(value[handle]) : "")

  function renderField(handle: 0 | 1) {
    const side = handle === 0 ? "from" : "to"
    const id = `nosto-price-${side}-${facet.id}`
    return (
      <div className={`filter__price__field filter__price__${side}`}>
        {isPrice && <span className="filter__price__currency">{text.currency}</span>}
        <input
          key={shown(handle)}
          className="filter__price__input"
          id={id}
          type="number"
          defaultValue={shown(handle)}
          placeholder={String(handle === 0 ? low : high)}
          min={low}
          max={high}
          onChange={e => onField(handle, e.currentTarget.value)}
        />
        <label htmlFor={id}>{handle === 0 ? text.from : text.to}</label>
      </div>
    )
  }

  return (
    <FilterGroup title={facet.name} count={isSelected ? 1 : 0}>
      <div className="filter__price" data-nosto-element="facet">
        <ThemeRange
          min={low}
          max={high}
          value={value}
          onChange={onChange}
          onInput={setDragged}
          label={facet.name}
        />
        <div className="filter__price__fields">
          {renderField(0)}
          <div className="filter__price__spacer">-</div>
          {renderField(1)}
        </div>
      </div>
    </FilterGroup>
  )
}

