import { fireEvent, render } from "@testing-library/preact"
import { describe, expect, it, vi } from "vitest"
import ActiveFilters from "@/shared/filters/ActiveFilters"

const removeAll = vi.fn()
const removeBrand = vi.fn()
let filters: { name: string; field: string; value: string; remove: () => void }[] = []

vi.mock("@nosto/search-js/preact/hooks", () => ({
  useProductFilters: () => ({ filters, removeAll })
}))

describe("ActiveFilters", () => {
  it("renders nothing without filters", () => {
    filters = []
    const { container } = render(<ActiveFilters />)
    expect(container.innerHTML).toBe("")
  })

  it("renders theme chips, formats price and removes on click", () => {
    filters = [
      { name: "Vendor", field: "brand", value: "BaubleBar", remove: removeBrand },
      { name: "Price", field: "price", value: "15 - 378", remove: vi.fn() }
    ]
    const { container, getByText } = render(<ActiveFilters />)
    const chips = Array.from(container.querySelectorAll(".active__filters__remove")).map(c => c.textContent)
    expect(chips).toEqual(["BaubleBar", "$15 - $378"])

    fireEvent.click(getByText("BaubleBar"))
    expect(removeBrand).toHaveBeenCalled()
    fireEvent.click(getByText("Clear Filters"))
    expect(removeAll).toHaveBeenCalled()
  })
})

