import { fireEvent, render } from "@testing-library/preact"
import { describe, expect, it, vi } from "vitest"
import { SearchStatsFacet } from "@nosto/nosto-js/client"
import RangeFacet from "@/shared/filters/RangeFacet"
import { FilterDrawerProvider } from "@/shared/filters/FilterDrawerContext"

const updateRange = vi.fn()
let range: [number | undefined, number | undefined] = [undefined, undefined]

vi.mock("@nosto/search-js/preact/hooks", () => ({
  useRange: () => ({ min: 119.5, max: 797.2, range, updateRange })
}))

const priceFacet = { id: "price", field: "skus.price", name: "Price", type: "stats", min: 119.5, max: 797.2 } as SearchStatsFacet

function renderFacet() {
  const { container } = render(
    <FilterDrawerProvider>
      <RangeFacet facet={priceFacet} />
    </FilterDrawerProvider>
  )
  const [from, to] = Array.from(container.querySelectorAll<HTMLInputElement>(".filter__price__input"))
  const low = container.querySelector<HTMLElement>(".range__dot--left")!
  return { container, from, to, low }
}

describe("RangeFacet", () => {
  it("starts a price slider at 0 like the theme, with $ From / To inputs showing placeholders", () => {
    range = [undefined, undefined]
    const { container, from, to, low } = renderFacet()
    expect(low.getAttribute("aria-valuemin")).toBe("0")
    expect(low.getAttribute("aria-valuemax")).toBe("798")
    expect([from.value, from.placeholder, to.value, to.placeholder]).toEqual(["", "0", "", "798"])
    expect(Array.from(container.querySelectorAll(".filter__price__currency")).map(c => c.textContent)).toEqual([
      "$",
      "$"
    ])
  })

  it("shows the filtered ends in the inputs", () => {
    range = [200, undefined]
    const { from, to } = renderFacet()
    expect([from.value, to.value]).toEqual(["200", ""])
  })

  it("applies a typed value, clamped to the range", () => {
    range = [undefined, undefined]
    const { from, to } = renderFacet()
    fireEvent.change(from, { target: { value: "150" } })
    expect(updateRange).toHaveBeenLastCalledWith([150, undefined])
    fireEvent.change(to, { target: { value: "5000" } })
    expect(updateRange).toHaveBeenLastCalledWith([undefined, undefined])
  })
})

