async (page) => {
  await page.goto('https://www.elietahari.com/search?q=dress&preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(9000);
  await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
  await page.locator('button.popout__toggle', { hasText: /^Filters/ }).filter({ visible: true }).first().click();
  await page.waitForTimeout(1000);
  const group = page.locator('.collection__sidebar__slide-out.expanded .filter-group', { hasText: 'Price' });
  await group.locator('summary').first().click();
  await page.waitForTimeout(800);
  const read = () => page.evaluate(() => {
    const g = [...document.querySelectorAll('.collection__sidebar__slide-out.expanded .filter-group')].find(x => /^price/i.test(x.querySelector('summary')?.textContent.trim() || ''));
    return { theme: Shopify.theme.id, inputs: [...g.querySelectorAll('.filter__price__input')].map(i => `${i.value}|${i.placeholder}`), leftDotX: Math.round(g.querySelector('.range__dot--left').getBoundingClientRect().x), url: location.search, heading: g.querySelector('summary').textContent.trim().replace(/\s+/g, ' '), view: document.querySelector('.collection__sidebar__buttons .btn--solid')?.textContent.trim() };
  });
  const unfiltered = await read();
  const from = group.locator('.filter__price__input').first();
  await from.fill('300');
  await from.press('Enter');
  await page.waitForTimeout(3500);
  const typed = await read();
  await page.screenshot({ path: '.playwright-mcp/qa/dev-price-typed.png', clip: { x: 0, y: 0, width: 400, height: 450 } });
  return { unfiltered, typed };
}

