async (page) => {
  await page.goto('https://www.elietahari.com/search?q=dress&preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(9000);
  await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
  await page.locator('button.popout__toggle', { hasText: /^Filters/ }).filter({ visible: true }).first().click();
  await page.waitForTimeout(1000);
  const group = page.locator('.collection__sidebar__slide-out.expanded .filter-group', { hasText: 'Price' });
  await group.locator('summary').first().click();
  await page.waitForTimeout(800);
  const right = group.locator('.range__dot--right');
  const b = await right.boundingBox();
  const inputs = () => group.locator('.filter__price__input').evaluateAll(els => els.map(e => e.value));
  await page.mouse.move(b.x + 18, b.y + 18);
  await page.mouse.down();
  await page.mouse.move(b.x - 100, b.y + 18, { steps: 8 });
  const during = await inputs();
  await page.mouse.up();
  await page.waitForTimeout(3500);
  return { theme: await page.evaluate(() => Shopify.theme.id), during, after: await inputs(), url: page.url() };
}

