async (page) => {
  const out = {};
  for (const w of [390, 820, 1100]) {
    await page.setViewportSize({ width: w, height: 900 });
    for (const [label, url] of [['live', 'https://www.elietahari.com/collections/dresses?preview_theme_id=157927932041'], ['dev', 'https://www.elietahari.com/collections/dresses?preview_theme_id=158466539657&nostodebug=true']]) {
      await page.goto(url);
      await page.waitForTimeout(8000);
      await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
      await page.screenshot({ path: `.playwright-mcp/qa/${label}-plp-${w}.png` });
      (out[w] ||= {})[label] = await page.evaluate(() => {
        const R = e => { if (!e) return null; const b = e.getBoundingClientRect(); return [b.x, b.y, b.width, b.height].map(Math.round); };
        const grid = [...document.querySelectorAll('[data-products-grid] .grid')].find(g => g.offsetParent);
        const nav = document.querySelector('.collection__nav');
        const card = grid?.querySelector('.product-item');
        return { theme: Shopify.theme.id, nosto: !!document.querySelector('[data-nosto-collection]'), cols: grid && getComputedStyle(grid).gridTemplateColumns, gap: grid && getComputedStyle(grid).gap, grid: R(grid), card: R(card),
          nav: R(nav), navItems: nav ? [...nav.querySelectorAll('button, a')].filter(e => e.offsetParent).map(e => ({ t: e.textContent.trim().replace(/\s+/g, ' ').slice(0, 25), r: R(e), fs: getComputedStyle(e).fontSize })) : null,
          title: (e => e && { r: R(e), fs: getComputedStyle(e).fontSize })(card?.querySelector('.product-item__title')) };
      });
    }
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
}

