input.code:
async (page) => {
  const bodies = [];
  const h = async r => { if (/search\.nosto\.com/.test(r.url()) && r.request().method() === 'POST') { try { bodies.push(await r.json()); } catch {} } };
  page.on('response', h);
  await page.goto('https://www.baublebar.com/search?q=necklace');
  await page.waitForTimeout(9000);
  page.off('response', h);
  const color = bodies.map(b => b?.data?.search?.products?.facets).flat().filter(Boolean).find(f => /color/i.test(f.name));
  const dom = await page.evaluate(() => {
    const sw = [...document.querySelectorAll('.rs-filter__color-swatch, .filter-group__swatch, [class*=swatch]')].filter(e => e.closest('[data-nosto-filters], .collection__sidebar, .collection__sidebar__slide-out')).slice(0, 4);
    return { theme: window.Shopify?.theme?.name, swatches: sw.map(e => ({ html: e.outerHTML.slice(0, 160), bg: getComputedStyle(e).backgroundColor, bgImg: getComputedStyle(e).backgroundImage.slice(0, 60) })), varBlue: getComputedStyle(document.querySelector('.rs-filter__color-swatch') || document.body).getPropertyValue('--blue') };
  });
  return { facet: color && { field: color.field, values: color.data.slice(0, 6).map(d => ({ v: d.value, visual: d.visual })) }, dom };
}

