async (page) => {
  const out = {};
  const cases = [
    ['coll', 'https://www.elietahari.com/collections/dresses?filter.v.price.gte=5000&preview_theme_id=157927932041'],
    ['search', 'https://www.elietahari.com/search?q=dress&filter.v.price.gte=5000&preview_theme_id=157927932041'],
    ['searchNone', 'https://www.elietahari.com/search?q=zzqxv&preview_theme_id=157927932041'],
  ];
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    for (const [label, url] of cases) {
      await page.goto(url);
      await page.waitForTimeout(5000);
      await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
      await page.screenshot({ path: `.playwright-mcp/qa/live-noresults-${label}-${w}.png` });
      out[`${label}-${w}`] = await page.evaluate(() => {
        const nr = document.querySelector('.no-results');
        const R = e => { if (!e) return null; const b = e.getBoundingClientRect(); return [b.x, b.y, b.width, b.height].map(Math.round); };
        return { theme: Shopify.theme.id,
          caption: document.querySelector('.search__caption')?.textContent.trim().replace(/\s+/g, ' '),
          nav: !!document.querySelector('.collection__nav') && [...document.querySelector('.collection__nav').querySelectorAll('button')].filter(b => b.offsetParent).map(b => b.textContent.trim().replace(/\s+/g, ' ').slice(0, 20)),
          noResultsHTML: nr?.outerHTML.replace(/\s+/g, ' ').slice(0, 600), nrRect: R(nr),
          nrFont: nr && (s => ({ fs: s.fontSize, ta: s.textAlign, ff: s.fontFamily }))(getComputedStyle(nr.querySelector('p') || nr)),
          btn: (b => b && { text: b.textContent.trim(), cls: b.className, rect: R(b), href: b.getAttribute('href') })(nr?.querySelector('a, button')),
          drawerChips: [...document.querySelectorAll('.active__filters__remove')].map(c => c.textContent.trim()) };
      });
    }
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
}

