    body: JSON.stringify({ query: `query($p: InputSearchProducts, $q: String){ search(accountId:"shopify-35089973385", query:$q, products:$p){ products { total facets { ... on SearchTermsFacet { name data { value count } } ... on SearchStatsFacet { name min max } } } } }`, variables: { p: products, q: query } }) }).then(r => r.json());
  const filtered = await q({ categoryId: "180839874697", size: 1, filter: [{ field: "skus.price", range: [{ gte: "5000" }] }] });
  const nomatch = await q({ size: 1 }, "xqzvbnmk");
  const s = r => r.errors ? r.errors[0].message : { total: r.data.search.products.total, facets: r.data.search.products.facets?.map(f => `${f.name}:${f.data ? f.data.length + ' values' : f.min + '-' + f.max}`) };
  return { filteredToZero: s(filtered), noMatch: s(nomatch) };
}

