import { useProductFilters } from "@nosto/search-js/preact/hooks"
import { getCurrentUrlState, getUrlFromState } from "@/lib/url"
import { strings } from "@/lib/i18n"

type Props = {
  /** The collection page adds a Reset button that clears filters (sections/collection.liquid); search doesn't */
  reset?: boolean
}

/**
 * The theme's empty grid (`.no-results` in sections/search.liquid and collection.liquid). The page keeps its
 * caption, toolbar and filter drawer around it, like the theme, so shoppers can loosen their filters.
 */
export default function NoResults({ reset = false }: Props) {
  const { removeAll } = useProductFilters()
  const text = strings()

  function onReset(e: Event) {
    e.preventDefault()
    removeAll()
  }

  return (
    <div className="grid">
      <div className="no-results">
        <p>
          <strong>{text.noMatches}</strong>
        </p>
        {reset && (
          <a
            className="btn caps btn--primary btn--solid"
            href={getUrlFromState({ ...getCurrentUrlState(), filter: undefined, page: undefined })}
            onClick={onReset}
          >
            <span>{text.reset}</span>
          </a>
        )}
      </div>
    </div>
  )
}

