import { useNostoAppState } from "@nosto/search-js/preact/hooks"
import { format, strings } from "@/lib/i18n"

/**
 * No-results state using the theme's markup and copy (sections/search.liquid).
 */
export default function NoResults() {
  const query = useNostoAppState(state => state.response.query)
  const text = strings()

  return (
    <>
      <p className="search__caption caps">{format(text.noResults, { terms: query ?? "" })}</p>
      <div className="grid-outer">
        <div className="grid">
          <div className="no-results">
            <p>
              <strong>{text.noMatches}</strong>
            </p>
          </div>
        </div>
      </div>
    </>
  )
}

