  });
  const cases = [
    ['coll', 'https://www.elietahari.com/collections/dresses?filter.skus.price.gte=5000&preview_theme_id=158466539657&nostodebug=true'],
    ['search', 'https://www.elietahari.com/search?q=dress&filter.skus.price.gte=5000&preview_theme_id=158466539657&nostodebug=true'],
    ['none', 'https://www.elietahari.com/search?q=xqzvbnmk&preview_theme_id=158466539657&nostodebug=true'],
  ];
  for (const w of [1440, 390]) {
