async (page) => {
  const out = {};
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    for (const [label, theme, extra] of [['live', '157927932041', ''], ['dev', '158466539657', '&nostodebug=true']]) {
      await page.goto(`https://www.elietahari.com/?preview_theme_id=${theme}${extra}`);
      await page.waitForTimeout(5000);
      await page.evaluate(() => {
        document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none');
        [...document.querySelectorAll('header-search-popdown summary, summary[title="Search"]')].find(e => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden')?.click();
      });
      await page.waitForTimeout(1500);
      await page.locator('header-search-popdown input[type="search"]').filter({ visible: true }).first().focus();
      await page.keyboard.type('xqzvbnmk', { delay: 60 });
      await page.waitForTimeout(4500);
      out[`${label}-${w}`] = await page.evaluate(() => {
        const R = e => { if (!e) return null; const b = e.getBoundingClientRect(); return [b.x, b.y, b.width, b.height].map(Math.round); };
        const d = [...document.querySelectorAll('.predictive-search')].find(e => e.getClientRects().length && getComputedStyle(e).visibility !== 'hidden' && getComputedStyle(e).opacity !== '0');
        const btn = d?.querySelector('.predictive-search__actions-button');
        return { theme: Shopify.theme.id, open: !!d, dropdown: R(d), button: btn && { text: btn.textContent.trim(), rect: R(btn), fs: getComputedStyle(btn).fontSize, tt: getComputedStyle(btn).textTransform }, visibleText: d && [...d.querySelectorAll('*')].filter(e => e.children.length === 0 && e.offsetParent && e.textContent.trim()).map(e => e.textContent.trim()) };
      });
    }
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.elietahari.com/collections/dresses?filter.skus.price.gte=5000&preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(8000);
  out.chip = await page.evaluate(() => [...document.querySelectorAll('[data-nosto-filters] .active__filters__remove')].map(c => c.textContent.trim()));
  return out;
}

