import json, re
def schema_settings(path, padding_defaults):
    s = open(path).read()
    j = json.loads(re.search(r'{%\s*schema\s*%}(.*?){%\s*endschema\s*%}', s, re.S).group(1))
    keep = [x for x in j['settings'] if x.get('id') in ('card_image_mode', 'color_scheme', 'padding_top', 'padding_bottom', 'padding_top_mobile', 'padding_bottom_mobile') or x.get('content') in ('Colors', 'Padding')]
    return keep

search_settings = schema_settings('sections/search.liquid', None)
coll_settings = schema_settings('sections/collection.liquid', None)

search = '''{%- comment -%}
  Nosto search results (template code: roswell-studios/Elie_Tahari_TAHARI_Nosto). Replaces the Search section on
  templates/search.json, which stays in the template disabled. Nosto portals the caption, toolbar, filter drawer
  and grid into the mount rs-nosto-results renders; pagination and columns come from "RS: Nosto Settings".
  Section settings are only ones the theme applies itself (padding, colour scheme) or that reach Nosto
  (card image mode). The <template> hands Nosto the Model | Product switcher markup — it sits outside the mount
  because Nosto clears the mount on first render.
{%- endcomment -%}

{%- liquid
  assign color_scheme = 'color-' | append: section.settings.color_scheme
  assign show_recently_viewed_indicator = settings.show_recently_viewed_indicator
-%}

{%- render 'stylesheet', name: 'collections.css' -%}
{%- render 'stylesheet', name: 'collection-bar.css' -%}

{%- style -%}
  .search-page {
    --PT: {{ section.settings.padding_top }}px;
    --PB: {{ section.settings.padding_bottom }}px;
    --PT-MOBILE: {{ section.settings.padding_top_mobile }}px;
    --PB-MOBILE: {{ section.settings.padding_bottom_mobile }}px;
  }
{%- endstyle -%}

<collection-component
  class="page search-page collection section-padding {{ color_scheme }}"
  data-section-type="collection"
  data-section-id="{{ section.id }}"
  data-sort="true"
>
  {%- render 'search-form' -%}

  <template data-nosto-model-switcher>
    {%- render 'collection-model-switcher' -%}
  </template>

  {%- render 'rs-nosto-results',
    mount: 'search',
    pagination: settings.rs_nosto_search_pagination,
    columns_desktop: settings.rs_nosto_search_columns_desktop,
    columns_mobile: settings.rs_nosto_search_columns_mobile,
    card_image_mode: section.settings.card_image_mode
  -%}
</collection-component>

{%- comment -%}
  Not loaded: collection.js / collection-filters-form.js (their popstate handler would fight Nosto's URL state).
{%- endcomment -%}
<script src="{{ 'collection-model-switcher.js' | asset_url }}" defer="defer"></script>

{%- if settings.quickview_enable -%}
  <script src="{{ 'product-info.js' | asset_url }}" defer="defer"></script>
{%- endif -%}

{%- if show_recently_viewed_indicator -%}
  <script src="{{ 'grid-item.js' | asset_url }}" defer></script>
{%- endif -%}

{% schema %}
''' + json.dumps({"name": "RS: Nosto search", "enabled_on": {"templates": ["search"]}, "settings": search_settings}, indent=2) + '''
{% endschema %}
'''

coll = '''{%- comment -%}
  Nosto collection page (template code: roswell-studios/Elie_Tahari_TAHARI_Nosto). Replaces the Collection
  products section on templates/collection.json, which stays in the template disabled. Nosto portals the toolbar,
  filter drawer and grid into the mount rs-nosto-results renders, and identifies the collection from its own page
  tagging. Pagination, columns and products per page come from "RS: Nosto Settings"; medium columns follow the
  Collection products section's rule. Section settings are only ones the theme applies itself (padding, colour
  scheme) or that reach Nosto (card image mode). The <template> hands Nosto the Model | Product switcher markup —
  it sits outside the mount because Nosto clears the mount on first render.
{%- endcomment -%}

{%- liquid
  assign color_scheme = 'color-' | append: section.settings.color_scheme
  assign show_recently_viewed_indicator = settings.show_recently_viewed_indicator

  assign rs_columns_desktop = settings.rs_nosto_collection_columns_desktop
  assign rs_columns_medium = 3
  if rs_columns_desktop == 2 or rs_columns_desktop == 4
    assign rs_columns_medium = 2
  endif
-%}

{%- render 'stylesheet', name: 'collections.css', inline: true -%}
{%- render 'stylesheet', name: 'collection-bar.css', inline: true -%}

{%- style -%}
  #Collection--{{ section.id }} {
    --PT: {{ section.settings.padding_top }}px;
    --PB: {{ section.settings.padding_bottom }}px;
    --PT-MOBILE: {{ section.settings.padding_top_mobile }}px;
    --PB-MOBILE: {{ section.settings.padding_bottom_mobile }}px;
  }
{%- endstyle -%}

<collection-component
  class="collection collection-products collection-{{ collection.handle }} section-padding {{ color_scheme }}"
  id="Collection--{{ section.id }}"
  data-section-id="{{ section.id }}"
  data-section-type="collection"
  data-sort="true"
  data-collection="{{ collection.url | default: '/collections/all' }}"
>
  <template data-nosto-model-switcher>
    {%- render 'collection-model-switcher' -%}
  </template>

  {%- comment -%} The header renders it when Nosto search is on {%- endcomment -%}
  {%- unless settings.rs_nosto_search_enabled -%}
    {%- render 'nosto-i18n' -%}
  {%- endunless -%}

  {%- render 'rs-nosto-results',
    mount: 'collection',
    pagination: settings.rs_nosto_collection_pagination,
    columns_desktop: rs_columns_desktop,
    columns_medium: rs_columns_medium,
    columns_mobile: settings.rs_nosto_collection_columns_mobile,
    page_size: settings.rs_nosto_collection_products_per_page,
    card_image_mode: section.settings.card_image_mode
  -%}
</collection-component>

{%- comment -%}
  Not loaded: collection.js / collection-filters-form.js (their popstate handler would fight Nosto's URL state)
  and rs-infinite-scroll.js (Nosto paginates).
{%- endcomment -%}
<script src="{{ 'collection-model-switcher.js' | asset_url }}" defer="defer"></script>

{%- if settings.quickview_enable -%}
  <script src="{{ 'product-info.js' | asset_url }}" defer="defer"></script>
{%- endif -%}

{%- if show_recently_viewed_indicator -%}
  <script src="{{ 'grid-item.js' | asset_url }}" defer></script>
{%- endif -%}

{% schema %}
''' + json.dumps({"name": "RS: Nosto collection", "enabled_on": {"templates": ["collection"]}, "settings": coll_settings}, indent=2) + '''
{% endschema %}
'''
open('sections/rs-nosto-search.liquid', 'w').write(search)
open('sections/rs-nosto-collection.liquid', 'w').write(coll)
print("written")
EOF
