input.code:
async (page) => {
  const out = {};
  const pages = [['coll', '/collections/dresses'], ['search', '/search?q=dress']];
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    for (const [p, path] of pages) for (const [label, theme, extra] of [['live', '157927932041', ''], ['dev', '158466539657', '&nostodebug=true']]) {
      await page.goto(`https://www.elietahari.com${path}${path.includes('?') ? '&' : '?'}preview_theme_id=${theme}${extra}`);
      await page.waitForTimeout(8000);
      await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
      await page.screenshot({ path: `.playwright-mcp/qa/${label}-newsection-${p}-${w}.png` });
      out[`${p}-${w}-${label}`] = await page.evaluate(() => {
        const R = e => { if (!e) return null; const b = e.getBoundingClientRect(); return [b.x, b.y, b.width, b.height].map(Math.round); };
        const cc = [...document.querySelectorAll('collection-component')].find(e => e.offsetParent);
        const grid = [...document.querySelectorAll('[data-products-grid] .grid')].find(g => g.offsetParent);
        const s = cc && getComputedStyle(cc);
        return { theme: Shopify.theme.id, sections: [...document.querySelectorAll('[id^="shopify-section-template"]')].map(e => e.id.replace(/^shopify-section-template--\d+__/, '')),
          cc: cc && { cls: cc.className, pad: [s.paddingTop, s.paddingBottom], bg: s.backgroundColor }, nav: R(document.querySelector('.collection__nav')), grid: grid && { r: R(grid), cols: getComputedStyle(grid).gridTemplateColumns }, firstCard: R(grid?.firstElementChild), caption: R(document.querySelector('.search__caption')) };
      });
    }
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
}

