input.code:
async (page) => {
  const out = {};
  const state = () => page.evaluate(() => {
    const grid = [...document.querySelectorAll('[data-products-grid] .grid')].find(g => g.offsetParent);
    const links = [...grid.querySelectorAll('.product-item a.product-link, .product-item a[href*="/products/"]')].map(a => new URL(a.href).pathname);
    const cards = grid.querySelectorAll('.product-item').length;
    const uniq = new Set(links.map(l => l.split('?')[0]));
    const pag = [...document.querySelectorAll('.pagination, .pagination__loading, [class*=ajaxinate], .ns-load-more, .btn__loader')].filter(e => e.getClientRects().length).map(e => e.className.toString().slice(0, 40));
    return { cards, uniqueProducts: uniq.size, url: location.search, scrollH: document.documentElement.scrollHeight, pag };
  });
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    for (const [label, url] of [['live', 'https://www.elietahari.com/collections/dresses?preview_theme_id=157927932041'], ['dev', 'https://www.elietahari.com/collections/dresses?preview_theme_id=158466539657&nostodebug=true']]) {
      await page.goto(url);
      await page.waitForTimeout(7000);
      await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
      const steps = [await state()];
      for (let i = 0; i < 3; i++) {
        await page.evaluate(() => window.scrollTo(0, document.documentElement.scrollHeight));
        await page.waitForTimeout(4500);
        steps.push(await state());
      }
      out[`${label}-${w}`] = { theme: await page.evaluate(() => Shopify.theme.id), steps };
    }
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
}

