input.command:
cd ~/Documents/roswell-studios/Elie_Tahari_TAHARI_2026-nosto-search && cat > sections/rs-nosto-carousel.liquid <<'EOF'
{%- comment -%}
  RS: Nosto carousel — a Nosto recommendation campaign rendered in the theme's own carousel and product card, for
  the homepage, PDP, 404 and category pages. Only the Nosto placement ID changes between uses. Nosto's
  <nosto-section-campaign> (loaded by the Nosto bundle, template code: roswell-studios/Elie_Tahari_TAHARI_Nosto)
  fetches the placement's products and renders sections/rs-nosto-carousel-items.liquid for them; the heading is
  the campaign title from Nosto Admin. Layout and spacing follow the PDP's Product recommendations section
  (sections/related.liquid as set in templates/product.json: 4 per row, slider on mobile, 4px gaps).
{%- endcomment -%}

{%- liquid
  assign placement = section.settings.placement | strip
  assign color_scheme = 'color-' | append: section.settings.color_scheme
-%}

{%- if placement != blank -%}
  {%- render 'stylesheet', name: 'related.css' -%}

  {%- style -%}
    #RsNostoCarousel--{{ section.id }} .grid {
      gap: 4px 4px;
      --gap: 4px;
    }

    @media only screen and (max-width: 749px) {
      #RsNostoCarousel--{{ section.id }} .grid {
        gap: 0 0;
      }
    }
  {%- endstyle -%}

  <div
    class="related__wrapper {{ color_scheme }}"
    id="RsNostoCarousel--{{ section.id }}"
    style="--PT: {{ section.settings.padding_top }}px; --PB: {{ section.settings.padding_bottom }}px; --PT-MOBILE: {{ section.settings.padding_top_mobile }}px; --PB-MOBILE: {{ section.settings.padding_bottom_mobile }}px;"
  >
    <div class="related__products section-padding">
      <div class="tab-content current tabs__recommendation">
        <div style="--column-count: 4; --COLUMNS: 4; --COLUMNS-MEDIUM: 2; --COLUMNS-SMALL: 2; --COLUMNS-MOBILE: 2;">
          <nosto-section-campaign
            placement="{{ placement | escape }}"
            section="rs-nosto-carousel-items"
            title-selector="[data-nosto-title]"
          ></nosto-section-campaign>
        </div>
      </div>
    </div>
  </div>

  {%- if settings.quickview_enable -%}
    <script src="{{ 'product-info.js' | asset_url }}" defer="defer"></script>
  {%- endif -%}

  {%- if settings.show_recently_viewed_indicator -%}
    <script src="{{ 'grid-item.js' | asset_url }}" defer></script>
  {%- endif -%}
{%- elsif request.design_mode -%}
  <div class="section-padding">
    <p class="center">Add a Nosto placement ID to show this carousel.</p>
  </div>
{%- endif -%}

{% schema %}
{
  "name": "RS: Nosto carousel",
  "settings": [
    {
      "type": "text",
      "id": "placement",
      "label": "Nosto placement ID",
      "info": "The placement ID of a recommendation campaign in Nosto Admin. The heading is the campaign's title."
    },
    {
      "type": "header",
      "content": "Colors"
    },
    {
      "type": "color_scheme",
      "id": "color_scheme",
      "default": "scheme_1",
      "label": "Color scheme"
    },
    {
      "type": "header",
      "content": "Padding"
    },
    {
      "type": "range",
      "id": "padding_top",
      "min": 0,
      "max": 100,
      "step": 1,
      "unit": "px",
      "label": "Top",
      "default": 50
    },
    {
      "type": "range",
      "id": "padding_bottom",
      "min": 0,
      "max": 100,
      "step": 1,
      "unit": "px",
      "label": "Bottom",
      "default": 24
    },
    {
      "type": "range",
      "id": "padding_top_mobile",
      "min": 0,
      "max": 100,
      "step": 1,
      "unit": "px",
      "label": "Top (mobile)",
      "default": 40
    },
    {
      "type": "range",
      "id": "padding_bottom_mobile",
      "min": 0,
      "max": 100,
      "step": 1,
      "unit": "px",
      "label": "Bottom (mobile)",
      "default": 16
    }
  ],
  "presets": [
    {
      "name": "RS: Nosto carousel"
    }
  ]
}
{% endschema %}
EOF
shopify theme check --output json 2>/dev/null > /tmp/tc3.json; python3 -c "
import json
d=json.load(open('/tmp/tc3.json'))
for f in d:
  if 'rs-nosto-carousel' in f['path']:
    for o in f['offenses']: print(f['path'].split('/')[-1], o['check'], o['severity'], o.get('start_row'), o['message'][:110])
print('done')"

