input.code:
async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.elietahari.com/collections/new-dresses?preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(8000);
  return await page.evaluate(async () => {
    const placements = [...document.querySelectorAll('.nosto_element, [id^="nosto"], nosto-campaign, nosto-section-campaign')].map(e => ({ tag: e.tagName, id: e.id, cls: e.className, placement: e.getAttribute('placement'), section: e.closest('[id^="shopify-section"]')?.id, text: e.textContent.trim().slice(0, 60) }));
    const api = await new Promise(r => window.nostojs(r));
    const pagePlacements = api.placements.getPlacements();
    const handles = [...document.querySelectorAll('[data-nosto-collection] nosto-dynamic-card')].slice(0, 6).map(c => c.getAttribute('handle'));
    const html = await (await fetch(`/search?section_id=rs-nosto-carousel-items&q=${encodeURIComponent(handles.join(' OR '))}`)).text();
    const d = new DOMParser().parseFromString(html, 'text/html');
    const first = d.body.firstElementChild;
    return { theme: Shopify.theme.id, placements, pagePlacements, handles,
      section: { wrapper: first?.id, hasTitle: !!first?.querySelector('[data-nosto-title]'), slider: !!first?.querySelector('grid-slider'), cards: first?.querySelectorAll('.product-item').length, titles: [...(first?.querySelectorAll('.product-item__title') || [])].map(t => t.textContent.trim()), error: html.includes('Liquid error') ? html.match(/Liquid error[^<]*/)?.[0] : null } };
  });
}

