async () => {
  const api = await new Promise(r => window.nostojs(r));
  const res = await api.defaultSession().setResponseMode('JSON_ORIGINAL').viewCategory('Dresses & Jumpsuits').setPlacements(['categorypage-nosto-2']).load();
  const rec = res?.recommendations?.['categorypage-nosto-2'] || res?.campaigns?.recommendations?.['categorypage-nosto-2'];
  const q = (rec?.products || []).map(p => p.handle).join(' OR ');
  const section = q ? await (await fetch(`/search?section_id=rs-nosto-carousel-items&q=${encodeURIComponent(q)}`)).text() : '';
  return { keys: Object.keys(res || {}), recKeys: rec && Object.keys(rec), title: rec?.title, count: rec?.products?.length, products: (rec?.products || []).slice(0, 5).map(p => ({ name: p.name, handle: p.handle, url: p.url, id: p.product_id })), sectionCards: (section.match(/product-item__title/g) || []).length };
}

