async (page) => {
  const out = {};
  const measure = (sel) => page.evaluate((sel) => {
    const root = document.querySelector(sel);
    if (!root) return null;
    const R = e => { if (!e) return null; const b = e.getBoundingClientRect(); return [b.x, Math.round(b.width), Math.round(b.height)].map(Math.round); };
    const grid = root.querySelector('.grid');
    const card = grid?.querySelector('.product-item');
    const t = root.querySelector('.tab__title');
    return { titleText: t?.textContent.trim(), title: t && { fs: getComputedStyle(t).fontSize, tt: getComputedStyle(t).textTransform, ta: getComputedStyle(t).textAlign, r: R(t) },
      cols: grid && getComputedStyle(grid).gridAutoColumns + ' / ' + getComputedStyle(grid).gridTemplateColumns.slice(0, 40), gap: grid && getComputedStyle(grid).gap, card: R(card), cardTitleFs: card && getComputedStyle(card.querySelector('.product-item__title')).fontSize,
      arrows: [...root.querySelectorAll('button')].filter(b => b.offsetParent).length, pad: getComputedStyle(root.querySelector('.section-padding') || root).paddingTop };
  }, sel);
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    await page.goto('https://www.elietahari.com/products/gilded-knit-dress?preview_theme_id=158466539657&nostodebug=true');
    await page.waitForTimeout(8000);
    await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
    const handles = await page.evaluate(() => [...document.querySelectorAll('related-products .product-item a[href*="/products/"]')].map(a => new URL(a.href).pathname.split('/products/')[1]).filter((v, i, a) => a.indexOf(v) === i).slice(0, 8));
    await page.locator('related-products').first().scrollIntoViewIfNeeded();
    await page.waitForTimeout(1500);
    await page.locator('related-products').first().screenshot({ path: `.playwright-mcp/qa/pdp-related-${w}.png` });
    const pdp = await measure('related-products');
    // Our section, fed the same products, inserted right after the PDP carousel
    await page.evaluate(async (handles) => {
      const html = await (await fetch(`/search?section_id=rs-nosto-carousel-items&q=${encodeURIComponent(handles.join(' OR '))}`)).text();
      const inner = new DOMParser().parseFromString(html, 'text/html').body.firstElementChild.innerHTML;
      const host = document.createElement('div');
      host.innerHTML = `<style>#RsNostoCarousel--test .grid{gap:4px 4px;--gap:4px}@media only screen and (max-width:749px){#RsNostoCarousel--test .grid{gap:0 0}}</style>
        <div class="related__wrapper color-scheme-1" id="RsNostoCarousel--test" style="--PT:50px;--PB:24px;--PT-MOBILE:40px;--PB-MOBILE:16px;"><div class="related__products section-padding"><div class="tab-content current tabs__recommendation"><div style="--column-count:4;--COLUMNS:4;--COLUMNS-MEDIUM:2;--COLUMNS-SMALL:2;--COLUMNS-MOBILE:2;"><nosto-section-campaign placement="test" section="rs-nosto-carousel-items" data-test>${inner}</nosto-section-campaign></div></div></div></div>`;
      host.querySelector('[data-nosto-title]').textContent = 'Curated for you';
      document.querySelector('related-products').after(host);
    }, handles);
    await page.waitForTimeout(4000);
    await page.locator('#RsNostoCarousel--test').scrollIntoViewIfNeeded();
    await page.waitForTimeout(1500);
    await page.locator('#RsNostoCarousel--test').screenshot({ path: `.playwright-mcp/qa/nosto-carousel-${w}.png` });
    out[w] = { theme: await page.evaluate(() => Shopify.theme.id), handles: handles.length, pdp, ours: await measure('#RsNostoCarousel--test') };
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
}

