async (page) => {
  const ctx = await page.context().browser().newContext({ viewport: { width: 1440, height: 900 } });
  const p = await ctx.newPage();
  await p.goto('https://www.elietahari.com/collections/dresses?preview_theme_id=158466539657');
  await p.waitForTimeout(8000);
  const res = await p.evaluate(async () => {
    const api = await new Promise(r => window.nostojs(r));
    const viaComponent = await api.createRecommendationRequest({ includeTagging: true }).disableCampaignInjection().setElements(['categorypage-nosto-1']).setResponseMode('JSON_ORIGINAL').load();
    const viaSession = await api.defaultSession().setResponseMode('JSON_ORIGINAL').viewCategory('Dresses & Jumpsuits').setPlacements(['categorypage-nosto-1']).load();
    const fmt = r => (r?.products || []).slice(0, 3).map(x => `${x.name} | ${x.handle}`);
    return { theme: Shopify.theme.id, debugBar: !!document.querySelector('nostodebug-bar'), componentRequest: fmt(viaComponent.recommendations['categorypage-nosto-1']), sessionRequest: fmt(viaSession.recommendations['categorypage-nosto-1']), wcDefined: !!customElements.get('nosto-section-campaign') };
  });
  // and the real component, end to end
  const comp = await p.evaluate(async () => {
    const el = document.createElement('nosto-section-campaign');
    el.setAttribute('placement', 'categorypage-nosto-1'); el.setAttribute('section', 'rs-nosto-carousel-items'); el.setAttribute('title-selector', '[data-nosto-title]');
    document.querySelector('main').appendChild(el);
    await new Promise(r => setTimeout(r, 7000));
    return { cards: el.querySelectorAll('.product-item').length, title: el.querySelector('[data-nosto-title]')?.textContent, names: [...el.querySelectorAll('.product-item__title')].slice(0, 3).map(t => t.textContent.trim()) };
  });
  await ctx.close();
  return { ...res, componentEndToEnd: comp };
}

