async (page) => {
  const out = {};
  const handles = ['augustina-lace-dress-in-black-onyx', 'claire-velvet-dress-in-midnight-paisley', 'products-mila-milano-sculpt-dress-black', 'yael-ruched-micro-mesh-dress-in-eclipse-petals', 'fringe-hem-dress-er5yf605-black'];
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    await page.goto('https://www.elietahari.com/collections/new-dresses?preview_theme_id=158466539657&nostodebug=true');
    await page.waitForTimeout(7000);
    await page.evaluate(async (handles) => {
      document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none');
      // Exactly what RS: Nosto carousel outputs, with the items section's HTML for Nosto's real products
      const html = await (await fetch(`/search?section_id=rs-nosto-carousel-items&q=${encodeURIComponent(handles.join(' OR '))}`)).text();
      const inner = new DOMParser().parseFromString(html, 'text/html').body.firstElementChild.innerHTML;
      const host = document.createElement('div');
      host.innerHTML = `<style>#RsNostoCarousel--poc .grid{gap:4px 4px;--gap:4px}@media only screen and (max-width:749px){#RsNostoCarousel--poc .grid{gap:0 0}}</style>
        <div class="related__wrapper color-scheme-1" id="RsNostoCarousel--poc" style="--PT:50px;--PB:24px;--PT-MOBILE:40px;--PB-MOBILE:16px;"><div class="related__products section-padding"><div class="tab-content current tabs__recommendation"><div style="--column-count:4;--COLUMNS:4;--COLUMNS-MEDIUM:2;--COLUMNS-SMALL:2;--COLUMNS-MOBILE:2;"><nosto-section-campaign placement="poc" section="rs-nosto-carousel-items" init="false">${inner}</nosto-section-campaign></div></div></div></div>`;
      host.querySelector('[data-nosto-title]').textContent = 'Most Popular Products In This Category';
      const anchor = document.querySelector('[id$="__section_custom_code_ra6j73"]') || document.querySelector('footer');
      anchor.parentNode.insertBefore(host, anchor);
    }, handles);
    await page.waitForTimeout(4000);
    await page.locator('#RsNostoCarousel--poc').scrollIntoViewIfNeeded();
    await page.waitForTimeout(2500);
    await page.locator('#RsNostoCarousel--poc').screenshot({ path: `.playwright-mcp/qa/poc-carousel-${w}.png` });
    out[w] = await page.evaluate(() => { const g = document.querySelector('#RsNostoCarousel--poc .grid'); return { theme: Shopify.theme.id, cards: g?.children.length, cardW: g && Math.round(g.firstElementChild.getBoundingClientRect().width), arrows: [...document.querySelectorAll('#RsNostoCarousel--poc button')].filter(b => b.offsetParent).length }; });
    // PDP reference
    await page.goto('https://www.elietahari.com/products/augustina-lace-dress-in-black-onyx?preview_theme_id=158466539657&nostodebug=true');
    await page.waitForTimeout(8000);
    await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
    const rel = page.locator('related-products, [id^="RelatedProducts--"]').first();
    if (await rel.count()) { await rel.scrollIntoViewIfNeeded(); await page.waitForTimeout(3000); await rel.screenshot({ path: `.playwright-mcp/qa/pdp-carousel-${w}.png` }); out[w].pdp = await page.evaluate(() => { const g = document.querySelector('related-products .grid'); return g && { cards: g.children.length, cardW: Math.round(g.firstElementChild?.getBoundingClientRect().width || 0) }; }); }
    else out[w].pdp = 'no related-products on this PDP';
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
}

