input.code:
async (page) => {
  const handles = ['augustina-lace-dress-in-black-onyx', 'claire-velvet-dress-in-midnight-paisley', 'products-mila-milano-sculpt-dress-black', 'yael-ruched-micro-mesh-dress-in-eclipse-petals', 'fringe-hem-dress-er5yf605-black'];
  const measure = (root) => page.evaluate((root) => {
    const r = document.querySelector(root);
    const R = e => { if (!e) return null; const b = e.getBoundingClientRect(); return [Math.round(b.x), Math.round(b.width), Math.round(b.height)]; };
    const g = r?.querySelector('.grid'); const t = r?.querySelector('.tab__title');
    const vis = g ? [...g.children].filter(c => { const b = c.getBoundingClientRect(); return b.width && b.left >= -1 && b.right <= innerWidth + 1; }).length : 0;
    return { title: t && { text: t.textContent.trim(), x: R(t)[0], fs: getComputedStyle(t).fontSize, tt: getComputedStyle(t).textTransform }, grid: R(g), gridCls: g?.className, card: R(g?.querySelector('.product-item')), visibleCards: vis,
      cardTitleFs: (e => e && getComputedStyle(e).fontSize)(g?.querySelector('.product-item__title')), padTop: getComputedStyle(r.querySelector('.section-padding') || r).paddingTop, arrows: [...r.querySelectorAll('button')].filter(b => b.offsetParent).map(b => b.className.slice(0, 30)) };
  }, root);
  const out = {};
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    await page.goto('https://www.elietahari.com/products/augustina-lace-dress-in-black-onyx?preview_theme_id=158466539657&nostodebug=true');
    await page.waitForTimeout(9000);
    await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper, [class*=klaviyo], .needsclick').forEach(e => e.style.display = 'none'));
    await page.locator('related-products').first().scrollIntoViewIfNeeded(); await page.waitForTimeout(2000);
    const pdp = await measure('related-products');
    await page.locator('related-products').first().screenshot({ path: `.playwright-mcp/qa/cmp-pdp-${w}.png` });
    await page.goto('https://www.elietahari.com/collections/dresses?preview_theme_id=158466539657&nostodebug=true');
    await page.waitForTimeout(9000);
    await page.evaluate(async (handles) => {
      document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper, [class*=klaviyo], .needsclick').forEach(e => e.style.display = 'none');
      const el = document.querySelector('[id^="RsNostoCarousel--"] nosto-section-campaign');
      const html = await (await fetch(`/search?section_id=rs-nosto-carousel-items&q=${encodeURIComponent(handles.join(' OR '))}`)).text();
      el.innerHTML = new DOMParser().parseFromString(html, 'text/html').body.firstElementChild.innerHTML;
      el.querySelector('[data-nosto-title]').textContent = 'Most Popular Products In This Category';
    }, handles);
    await page.waitForTimeout(4000);
    await page.locator('[id^="RsNostoCarousel--"]').first().scrollIntoViewIfNeeded(); await page.waitForTimeout(2500);
    const ours = await measure('[id^="RsNostoCarousel--"]');
    await page.locator('[id^="RsNostoCarousel--"]').first().screenshot({ path: `.playwright-mcp/qa/cmp-ours-${w}.png` });
    out[w] = { theme: await page.evaluate(() => Shopify.theme.id), pdp, ours };
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
}

