async () => {
  const api = await new Promise(r => window.nostojs(r));
  const viaComponent = await api.createRecommendationRequest({ includeTagging: true }).disableCampaignInjection().setElements(['categorypage-nosto-1', 'categorypage-nosto-2']).setResponseMode('JSON_ORIGINAL').load();
  const viaSession = await api.defaultSession().setResponseMode('JSON_ORIGINAL').viewCategory('Dresses & Jumpsuits').setPlacements(['categorypage-nosto-1']).update();
  const f = r => r && { result_id: r.result_id, result_type: r.result_type, title: r.title, first: r.products?.[0]?.name, params: r.params && Object.keys(r.params) };
  return { theme: Shopify.theme.id, componentRequest: { one: f(viaComponent.recommendations['categorypage-nosto-1']), two: f(viaComponent.recommendations['categorypage-nosto-2']) }, sessionRequest: f(viaSession.recommendations?.['categorypage-nosto-1']) };
}

