async (page) => {
  await page.goto('https://www.elietahari.com/collections/dresses?preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(8000);
  return await page.evaluate(async () => {
    const api = await new Promise(r => window.nostojs(r));
    const r = await api.createRecommendationRequest({ includeTagging: true }).disableCampaignInjection().setElements(['categorypage-nosto-1', 'categorypage-nosto-2']).setResponseMode('JSON_ORIGINAL').load();
    const f = x => x && { result_id: x.result_id, result_type: x.result_type, title: x.title, products: x.products?.slice(0, 3).map(p => `${p.name} | ${p.handle}`) };
    const el = document.querySelector('[id^="RsNostoCarousel--"] nosto-section-campaign');
    return { theme: Shopify.theme.id, url: location.pathname + location.search, preview: document.cookie.includes('nostopreview') || !!document.querySelector('nostodebug-bar'), one: f(r.recommendations['categorypage-nosto-1']), two: f(r.recommendations['categorypage-nosto-2']), ourSectionCards: el?.querySelectorAll('.product-item').length };
  });
}

