input.code:
async (page) => {
  await page.setViewportSize({ width: 1440, height: 900 });
  await page.goto('https://www.elietahari.com/?preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(8000);
  return await page.evaluate(async () => {
    const api = await new Promise(r => window.nostojs(r));
    const ids = ['frontpage-nosto-1', 'frontpage-nosto-2', 'frontpage-nosto-3', 'frontpage-nosto-4', 'nosto-frontpage-1', 'nosto-frontpage-2', 'categorypage-nosto-1', 'categorypage-nosto-2', 'productpage-nosto-1', 'productpage-nosto-2', 'notfound-nosto-1', 'cartpage-nosto-1'];
    const r = await api.createRecommendationRequest({ includeTagging: true }).disableCampaignInjection().setElements(ids).setResponseMode('JSON_ORIGINAL').load();
    const out = {};
    for (const id of ids) { const x = r.recommendations?.[id]; out[id] = x ? `${x.result_type} | ${x.title} | ${x.products?.length} | ${x.products?.[0]?.name}` : '—'; }
    return { theme: Shopify.theme.id, pageType: api.pageTagging().pageType, pagePlacements: api.placements.getPlacements(), results: out };
  });
}

