async (page) => {
  await page.goto('https://www.elietahari.com/?preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(8000);
  return await page.evaluate(async () => {
    const api = await new Promise(r => window.nostojs(r));
    const req = () => api.createRecommendationRequest({ includeTagging: true }).disableCampaignInjection().setElements(['frontpage-nosto-1', 'categorypage-nosto-1']).setResponseMode('JSON_ORIGINAL').load();
    const f = x => x ? `${x.result_type} | ${x.products?.[0]?.name}` : '—';
    const before = await req();
    const variationBefore = api.pageTagging().variation;
    api.setTaggingProvider('variation', undefined);
    const after = await req();
    const variationAfter = api.pageTagging().variation;
    api.setTaggingProvider('variation', variationBefore);
    return { theme: Shopify.theme.id, withVariation: { v: variationBefore, front: f(before.recommendations['frontpage-nosto-1']), category: f(before.recommendations['categorypage-nosto-1']) }, withoutVariation: { v: variationAfter ?? null, front: f(after.recommendations['frontpage-nosto-1']), category: f(after.recommendations['categorypage-nosto-1']) } };
  });
}

