async (page) => {
  const out = {};
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    await page.goto('https://www.elietahari.com/?preview_theme_id=158466539657&nostodebug=true');
    await page.waitForTimeout(8000);
    out[w] = await page.evaluate(async () => {
      document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none');
      const api = await new Promise(r => window.nostojs(r));
      const el = document.querySelector('[id^="RsNostoCarousel--"] nosto-section-campaign');
      if (!el) return { theme: Shopify.theme.id, error: 'no RS: Nosto carousel on this page' };
      const placement = el.getAttribute('placement');
      api.setTaggingProvider('variation', undefined);
      await el.load();
      await new Promise(r => setTimeout(r, 3000));
      el.closest('[id^="RsNostoCarousel--"]').scrollIntoView({ block: 'center' });
      await new Promise(r => setTimeout(r, 2500));
      const R = e => { if (!e) return null; const b = e.getBoundingClientRect(); return [Math.round(b.x), Math.round(b.width), Math.round(b.height)]; };
      const g = el.querySelector('.grid'); const t = el.querySelector('[data-nosto-title]');
      const sec = el.closest('[id^="shopify-section"]');
      return { theme: Shopify.theme.id, placement, sectionIndex: [...document.querySelectorAll('main > [id^="shopify-section"], #MainContent > [id^="shopify-section"]')].indexOf(sec) + 1,
        title: t?.textContent.trim(), cards: g?.children.length, names: [...el.querySelectorAll('.product-item__title')].slice(0, 4).map(x => x.textContent.trim()), card: R(g?.querySelector('.product-item')), gridCls: g?.className,
        visible: g ? [...g.children].filter(c => { const b = c.getBoundingClientRect(); return b.width && b.left >= -1 && b.right <= innerWidth + 1; }).length : 0, clickTracking: el.getAttribute('data-nosto-ref') };
    });
    await page.locator('[id^="RsNostoCarousel--"]').first().screenshot({ path: `.playwright-mcp/qa/hp-nosto-carousel-${w}.png` });
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
