async (page) => {
  const out = {};
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    const reqs = [];
    const h = r => { const u = r.url(); if (u.includes('section_id=rs-nosto-carousel-items')) reqs.push('section'); };
    page.on('request', h);
    // Homepage: section 2 → loads now
    await page.goto('https://www.elietahari.com/?preview_theme_id=158466539657&nostodebug=true');
    await page.waitForTimeout(9000);
    const hp = await page.evaluate(() => {
      const host = document.querySelector('rs-nosto-carousel'); const wrap = host?.querySelector('[id^="RsNostoCarousel--"]');
      const imgs = [...(wrap?.querySelectorAll('.product-item img') || [])];
      return { theme: Shopify.theme.id, deferred: !!host?.querySelector('template[data-rs-nosto-deferred]'), shown: wrap && getComputedStyle(wrap).display !== 'none', cards: wrap?.querySelectorAll('.grid-item').length, title: wrap?.querySelector('[data-nosto-title]')?.textContent.trim(), eager: imgs.filter(i => i.loading === 'eager').length, highPriority: imgs.filter(i => i.getAttribute('fetchpriority') === 'high').length, lazy: imgs.filter(i => i.loading === 'lazy').length };
    });
    const hpSectionRequests = reqs.length; reqs.length = 0;
    // Collection: far below the grid → deferred
    await page.goto('https://www.elietahari.com/collections/dresses?preview_theme_id=158466539657&nostodebug=true');
    await page.waitForTimeout(8000);
    const before = await page.evaluate(() => { const host = document.querySelector('rs-nosto-carousel'); const wrap = host?.querySelector('[id^="RsNostoCarousel--"]'); return { deferred: !!host?.querySelector('template[data-rs-nosto-deferred]'), shown: wrap && getComputedStyle(wrap).display !== 'none', hostHeight: host && Math.round(host.getBoundingClientRect().height) }; });
    const sectionReqsBefore = reqs.length;
    await page.evaluate(async () => { for (let i = 0; i < 12; i++) { window.scrollTo(0, document.documentElement.scrollHeight); await new Promise(r => setTimeout(r, 1200)); } });
    await page.waitForTimeout(5000);
    const after = await page.evaluate(() => { const host = document.querySelector('rs-nosto-carousel'); const wrap = host?.querySelector('[id^="RsNostoCarousel--"]'); return { deferred: !!host?.querySelector('template[data-rs-nosto-deferred]'), shown: wrap && getComputedStyle(wrap).display !== 'none', cards: wrap?.querySelectorAll('.grid-item').length, title: wrap?.querySelector('[data-nosto-title]')?.textContent.trim() }; });
    page.off('request', h);
    out[w] = { homepage: { ...hp, sectionRequests: hpSectionRequests }, collection: { before: { ...before, sectionRequests: sectionReqsBefore }, afterScroll: { ...after, sectionRequests: reqs.length } } };
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
}

