content.content:
  the section is about one viewport away; turn it off for a carousel near the top of the page so it requests
  Nosto straight away. Card images are always lazy (they arrive after page load). The wrapper
  stays collapsed until it holds a product card, so a campaign with no real products takes no space.
{%- endcomment -%}

{%- liquid
  assign placement = section.settings.placement | strip
  assign color_scheme = 'color-' | append: section.settings.color_scheme

  assign load_now = true
  if section.settings.lazy_load
    assign load_now = false
  endif
-%}

{%- if placement != blank -%}
  {%- render 'stylesheet', name: 'related.css' -%}
  {%- render 'stylesheet', name: 'tabs.css' -%}

  {%- style -%}
    #RsNostoCarousel--{{ section.id }} .grid {
done
