    const cards = [...document.querySelectorAll('related-products .product-item, [id^="RelatedProducts--"] .product-item')];
    return { theme: Shopify.theme.id, cards: cards.length, perCard: cards.map(c => { const imgs = [...c.querySelectorAll('img')]; return imgs.map(i => `${i.getAttribute('loading')}/${i.getAttribute('fetchpriority') || '-'}`).join(','); }) };
  });
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    for (const [label, theme] of [['live', '157927932041'], ['dev', '158466539657']]) {
      await page.goto(`https://www.elietahari.com/products/augustina-lace-dress-in-black-onyx?preview_theme_id=${theme}`);
      await page.waitForTimeout(8000);
      await page.evaluate(() => document.querySelector('related-products')?.scrollIntoView());
      await page.waitForTimeout(3000);
      (out[w] ||= {})[label] = await grab();
    }
    out[w].identical = JSON.stringify(out[w].live.perCard) === JSON.stringify(out[w].dev.perCard);
