input.code:
async (page) => {
  const out = {};
  for (const w of [1440, 390]) {
    await page.setViewportSize({ width: w, height: 900 });
    let sectionReq = 0;
    const h = r => { if (r.url().includes('section_id=rs-nosto-carousel-items')) sectionReq++; };
    page.on('request', h);
    await page.goto('https://www.elietahari.com/?preview_theme_id=158466539657&nostodebug=true');
    await page.waitForTimeout(3000);
    const early = await page.evaluate(() => ({ theme: Shopify.theme.id, templateInHtml: !!document.querySelector('rs-nosto-carousel template[data-rs-nosto-deferred]'), scriptLoaded: !!customElements.get('rs-nosto-carousel') }));
    await page.evaluate(() => document.querySelector('rs-nosto-carousel')?.scrollIntoView({ block: 'center' }));
    await page.waitForTimeout(6000);
    const after = await page.evaluate(() => { const w = document.querySelector('[id^="RsNostoCarousel--"]'); const imgs = [...(w?.querySelectorAll('.product-item img') || [])]; return { cards: w?.querySelectorAll('.grid-item').length, shown: w && getComputedStyle(w).display !== 'none', title: w?.querySelector('[data-nosto-title]')?.textContent.trim(), eagerOrHigh: imgs.filter(i => i.loading === 'eager' || i.getAttribute('fetchpriority') === 'high').length }; });
    page.off('request', h);
    out[w] = { early, after, sectionRequests: sectionReq };
  }
  await page.setViewportSize({ width: 1440, height: 900 });
  return out;
}

