input.content:
"""Turns a Slack-style docs/comms/*.md draft (*bold*, `code`, "- " bullets) into an HTML page that copies into
Slack with formatting kept. A line of just `---` splits the draft into separate Slack messages; each gets its
own box and Copy button (copies the formatted message only). A single-message draft can also be copied with
select all.

Usage: python3 scripts/md-to-slack-html.py docs/comms/<draft>.md docs/comms/<draft>.html
"""
import html, re, sys

src, out = sys.argv[1], sys.argv[2]
text = open(src).read().rstrip('\n')


def inline(t):
    t = html.escape(t, quote=False)
    t = re.sub(r'`([^`]+)`', r'<code>\1</code>', t)
    return re.sub(r'(?<![\w*])\*([^*\n]+)\*(?![\w*])', r'<b>\1</b>', t)


def render(message):
    body, items = [], []

    def flush():
        if items:
            body.append('<ul>' + ''.join(f'<li>{i}</li>' for i in items) + '</ul>')
            items.clear()

    for line in message.strip('\n').split('\n'):
        if line.startswith('- '):
            items.append(inline(line[2:]))
            continue
        flush()
        body.append('<p>&nbsp;</p>' if not line.strip() else f'<p>{inline(line)}</p>')
    flush()
    return ''.join(body)


messages = [m for m in re.split(r'\n---\n', text) if m.strip()]
boxes = ''.join(
    f'<section><div class="bar"><span>Message {n} of {len(messages)}</span>'
    f'<button type="button" data-copy="m{n}">Copy</button></div><div class="msg" id="m{n}">{render(m)}</div></section>'
    for n, m in enumerate(messages, 1)
)

page = f'''<!doctype html><html><head><meta charset="utf-8"><title>Slack draft: {html.escape(src.split('/')[-1])}</title>
<style>
body{{font:15px/1.5 -apple-system,Helvetica,Arial,sans-serif;max-width:760px;margin:32px auto;padding:0 20px;background:#f6f6f6}}
section{{background:#fff;border:1px solid #ddd;border-radius:8px;margin:0 0 20px;padding:16px 20px}}
.bar{{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;color:#888;font-size:12px}}
button{{font:inherit;font-size:13px;padding:4px 14px;border:1px solid #bbb;border-radius:6px;background:#fff;cursor:pointer}}
p{{margin:0}}ul{{margin:0 0 0 1.2em;padding:0}}code{{font-family:Menlo,monospace;font-size:13px}}
</style></head>
<body>{boxes}
<script>
document.addEventListener('click', e => {{
  const id = e.target.dataset.copy;
  if (!id) return;
  const range = document.createRange();
  range.selectNodeContents(document.getElementById(id));
  const sel = getSelection();
  sel.removeAllRanges();
  sel.addRange(range);
  document.execCommand('copy');
  sel.removeAllRanges();
  e.target.textContent = 'Copied';
  setTimeout(() => (e.target.textContent = 'Copy'), 1500);
}});
</script></body></html>'''
open(out, 'w').write(page)
print(out, '-', len(messages), 'message(s)')

