input.code:
async (page) => {
  const out = {};
  const run = async (label, url) => {
    const reqs = [];
    const h = async r => { const u = r.url(); if (/connect\.nosto\.com\/(ev1|.*\/ev1)|\/ev1\?|nosto.*\/ev1/.test(u) || /connect\.nosto\.com/.test(u) && r.request().method() === 'POST') { let pv = null; try { const t = await r.text(); const m = t.match(/"pv"\s*:\s*(\d+)/); pv = m && +m[1]; } catch {} reqs.push({ path: new URL(u).pathname.slice(0, 40), method: r.request().method(), pv }); } };
    page.on('response', h);
    await page.goto(url);
    await page.waitForTimeout(9000);
    await page.evaluate(() => document.querySelector('rs-nosto-carousel')?.scrollIntoView());
    await page.waitForTimeout(4000);
    page.off('response', h);
    out[label] = { theme: await page.evaluate(() => Shopify.theme.id), carousel: await page.evaluate(() => !!document.querySelector('rs-nosto-carousel .grid-item')), nostoRequests: reqs };
  };
  await run('dev HP with carousel', 'https://www.elietahari.com/?preview_theme_id=158466539657&nostodebug=true');
  await run('dev HP reload', 'https://www.elietahari.com/?preview_theme_id=158466539657&nostodebug=true');
  return out;
}

