input.function:
async () => {
  const api = await new Promise(r => window.nostojs(r));
  const s = api.internal?.getSettings?.() || {};
  const keys = Object.keys(s).filter(k => /auto|load|inject|placement/i.test(k));
  return { theme: Shopify.theme.id, settings: Object.fromEntries(keys.map(k => [k, s[k]])), autoLoadFlag: s.autoLoad ?? s.autoload ?? s.disableAutoLoad ?? null };
}

