input.code:
async (page) => {
  await page.setViewportSize({ width: 1227, height: 1185 });
  const failed = [], statuses = {};
  const h = r => { const u = r.url(); if (u.includes('section_id=api-nosto-product-card')) { const s = r.status(); statuses[s] = (statuses[s] || 0) + 1; if (s >= 400) failed.push({ s, handle: u.split('/products/')[1]?.split('?')[0] }); } };
  page.on('response', h);
  await page.goto('https://www.elietahari.com/collections/bottoms-collection?p=5&preview_theme_id=158466539657&nostodebug=true');
  await page.waitForTimeout(9000);
  await page.evaluate(() => document.querySelectorAll('nostodebug-bar, csm-cookie-consent, #PBarNextFrameWrapper').forEach(e => e.style.display = 'none'));
  // go to the bottom of the grid like the screenshot, then sit still
  await page.evaluate(() => { const g = document.querySelector('[data-nosto-collection] .grid'); window.scrollTo(0, g.getBoundingClientRect().bottom + scrollY - 1100); });
  await page.waitForTimeout(12000);
  page.off('response', h);
  const cells = await page.evaluate(() => {
    const cs = [...document.querySelectorAll('[data-nosto-collection] .ns-card-cell')];
    const inView = c => { const b = c.getBoundingClientRect(); return b.bottom > 0 && b.top < innerHeight; };
    return { theme: Shopify.theme.id, total: cs.length,
